// ---------------------------------------------------------------- Cursor

final class Cursor: Equatable {
    let ns: NSCursor
    let name: String
    init(_ ns: NSCursor, _ name: String) { self.ns = ns; self.name = name }
    static func == (a: Cursor, b: Cursor) -> Bool { return a === b }

    // global top-left
    static var Position: Point {
        get {
            if let ev = CGEvent(source: nil) {
                let p = ev.location   // CG global coords are already top-left of the primary screen
                return PointT(Int(p.x.rounded(.down)), Int(p.y.rounded(.down)))
            }
            let m = NSEvent.mouseLocation
            return PointT(Int(m.x.rounded(.down)), Int((_Coords.primaryH - m.y).rounded(.down)))
        }
        set { CGWarpMouseCursorPosition(CGPoint(x: CGFloat(newValue.X), y: CGFloat(newValue.Y))) }
    }
    // instance mirror (inside Control subclasses `Cursor.Position` resolves to the Cursor *property*)
    var Position: Point { get { return Cursor.Position } set { Cursor.Position = newValue } }
    static var Current: Cursor { get { return Cursors.Default } set { newValue.ns.set() } }
    func ToString() -> String { return "[Cursor: " + name + "]" }
}

enum Cursors {
    static let Default = Cursor(NSCursor.arrow, "Default")
    static let Arrow = Cursor(NSCursor.arrow, "Arrow")
    static let Hand = Cursor(NSCursor.pointingHand, "Hand")
    static let IBeam = Cursor(NSCursor.iBeam, "IBeam")
    static let Cross = Cursor(NSCursor.crosshair, "Cross")
    static let SizeAll = Cursor(NSCursor.openHand, "SizeAll")
    static let SizeWE = Cursor(NSCursor.resizeLeftRight, "SizeWE")
    static let SizeNS = Cursor(NSCursor.resizeUpDown, "SizeNS")
    static let No = Cursor(NSCursor.operationNotAllowed, "No")
    static let WaitCursor = Cursor(NSCursor.arrow, "WaitCursor")
}

// ---------------------------------------------------------------- Screen / SystemInformation

final class Screen: Equatable {
    let Bounds: Rectangle
    let WorkingArea: Rectangle
    let DeviceName: String
    let Primary: Bool
    let BitsPerPixel = 32
    let ns: NSScreen?

    init(_ s: NSScreen?, _ index: Int) {
        ns = s
        if let s = s {
            let b = _Coords.fromCocoa(s.frame), w = _Coords.fromCocoa(s.visibleFrame)
            Bounds = RectangleT(b.0, b.1, b.2, b.3)
            WorkingArea = RectangleT(w.0, w.1, w.2, w.3)
            var name = "\\\\.\\DISPLAY" + String(index + 1)
            if let n = s.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? NSNumber { name += ":" + n.stringValue }
            DeviceName = name
        } else {
            Bounds = RectangleT(0, 0, 1440, 900); WorkingArea = RectangleT(0, 25, 1440, 875); DeviceName = "\\\\.\\DISPLAY1"
        }
        Primary = index == 0
    }
    static func == (a: Screen, b: Screen) -> Bool { return a.DeviceName == b.DeviceName && a.Bounds == b.Bounds }

    static var AllScreens: [Screen] {
        let ss = NSScreen.screens
        if ss.isEmpty { return [Screen(nil, 0)] }
        var out: [Screen] = []
        for (i, s) in ss.enumerated() { out.append(Screen(s, i)) }
        return out
    }
    static var PrimaryScreen: Screen { return AllScreens[0] }

    static func FromPoint(_ p: Point) -> Screen {
        let all = AllScreens
        var best = all[0]
        var bestD = Int.max
        for s in all {
            let b = s.Bounds
            if p.X >= b.X && p.X < b.X + b.Width && p.Y >= b.Y && p.Y < b.Y + b.Height { return s }
            let dx = p.X < b.X ? b.X - p.X : (p.X >= b.X + b.Width ? p.X - (b.X + b.Width - 1) : 0)
            let dy = p.Y < b.Y ? b.Y - p.Y : (p.Y >= b.Y + b.Height ? p.Y - (b.Y + b.Height - 1) : 0)
            let d = dx * dx + dy * dy
            if d < bestD { bestD = d; best = s }
        }
        return best
    }
    static func FromRectangle(_ r: Rectangle) -> Screen {
        let all = AllScreens
        var best: Screen? = nil
        var bestA = 0
        for s in all {
            let b = s.Bounds
            let l = max(b.X, r.X), t = max(b.Y, r.Y), rr = min(b.X + b.Width, r.X + r.Width), bb = min(b.Y + b.Height, r.Y + r.Height)
            let a = rr > l && bb > t ? (rr - l) * (bb - t) : 0
            if a > bestA { bestA = a; best = s }
        }
        return best ?? FromPoint(PointT(r.X + r.Width / 2, r.Y + r.Height / 2))
    }
    static func FromHandle(_ h: IntPtr) -> Screen {
        if let f = Form._FromHandle(h) { return FromRectangle(f.Bounds) }
        var r = W.RECT()
        if W.GetWindowRect(h, &r) { return FromRectangle(RectangleT(r.L, r.T, r.R - r.L, r.B - r.T)) }
        return PrimaryScreen
    }
    static func FromControl(_ c: Control) -> Screen {
        if let f = c as? Form { return FromRectangle(f.Bounds) }
        return PrimaryScreen
    }
    static func GetBounds(_ p: Point) -> Rectangle { return FromPoint(p).Bounds }
    static func GetWorkingArea(_ p: Point) -> Rectangle { return FromPoint(p).WorkingArea }
}

enum SystemInformation {
    static var VirtualScreen: Rectangle {
        var l = Int.max, t = Int.max, r = Int.min, b = Int.min
        for s in Screen.AllScreens {
            let x = s.Bounds
            l = min(l, x.X); t = min(t, x.Y); r = max(r, x.X + x.Width); b = max(b, x.Y + x.Height)
        }
        return RectangleT(l, t, r - l, b - t)
    }
    static var PrimaryMonitorSize: Size { let b = Screen.PrimaryScreen.Bounds; return SizeT(b.Width, b.Height) }
    static var WorkingArea: Rectangle { return Screen.PrimaryScreen.WorkingArea }
    static var MonitorCount: Int { return max(1, NSScreen.screens.count) }
    static var DoubleClickTime: Int { return Int(NSEvent.doubleClickInterval * 1000) }
}

// ---------------------------------------------------------------- Timer (WinForms timer: main run loop, .common modes)

final class Timer {
    private var t: Foundation.Timer? = nil
    private var _interval = 100
    var Tick: (() -> Void)? = nil
    var Tag: Any? = nil
    init() { }
    init(_ interval: Int) { _interval = interval }
    var Interval: Int {
        get { return _interval }
        set { _interval = max(1, newValue); if t != nil { Stop(); Start() } }
    }
    var Enabled: Bool {
        get { return t != nil }
        set { if newValue { Start() } else { Stop() } }
    }
    func Start() {
        if t != nil { return }
        let make = { [weak self] () -> Void in
            guard let self = self, self.t == nil else { return }
            let tm = Foundation.Timer(timeInterval: Double(self._interval) / 1000.0, repeats: true) { [weak self] _ in
                self?.Tick?()
            }
            tm.tolerance = 0
            RunLoop.main.add(tm, forMode: .common)   // keeps firing during menu tracking / window drags
            self.t = tm
        }
        if Foundation.Thread.isMainThread { make() } else { DispatchQueue.main.async(execute: make) }
    }
    func Stop() { t?.invalidate(); t = nil }
    func Dispose() { Stop() }
}

// ---------------------------------------------------------------- Control

final class ControlCollection: Sequence {
    private(set) var items: [Control] = []
    unowned let owner: Control
    init(_ owner: Control) { self.owner = owner }
    func Add(_ c: Control) {
        if c.Parent === owner { return }
        if let p = c.Parent { p.Controls.Remove(c) }
        items.append(c)
        c.Parent = owner
        owner._childAdded(c)
    }
    func AddRange(_ cs: [Control]) { for c in cs { Add(c) } }
    func Remove(_ c: Control) {
        if let i = items.firstIndex(where: { $0 === c }) { items.remove(at: i); c.Parent = nil; c._nsView?.removeFromSuperview() }
    }
    func Clear() { for c in items { c.Parent = nil; c._nsView?.removeFromSuperview() }; items.removeAll() }
    func Contains(_ c: Control) -> Bool { return items.contains { $0 === c } }
    var Count: Int { return items.count }
    subscript(_ i: Int) -> Control { return items[i] }
    func makeIterator() -> IndexingIterator<[Control]> { return items.makeIterator() }
}

class Control {
    // bounds: global top-left for Forms, parent-client-relative for child controls
    var _x = 0, _y = 0, _w = 100, _h = 23
    var _text = ""
    var _font: FontT? = nil
    var _foreColor: Color? = nil
    var _backColor: Color? = nil
    var _visible = true
    var _enabled = true
    var Tag: Any? = nil
    var Name = ""
    var TabIndex = 0
    var TabStop = true
    var AutoSize = false { didSet { _autoSize() } }
    var Dock = 0
    var Anchor = 0
    weak var Parent: Control? = nil
    lazy var Controls = ControlCollection(self)
    var Cursor: CursorT! = Cursors.Default { didSet { _cursorChanged() } }
    var _disposed = false

    init() { }

    // ---- statics (WinForms Control.MouseButtons / ModifierKeys / MousePosition)
    static var MouseButtons: MouseButtons {
        let b = NSEvent.pressedMouseButtons
        var r = 0
        if b & 1 != 0 { r |= 0x100000 }
        if b & 2 != 0 { r |= 0x200000 }
        if b & 4 != 0 { r |= 0x400000 }
        return MouseButtonsT(raw: r)
    }
    static var ModifierKeys: Keys { return Keys.ModsFrom(NSEvent.modifierFlags) }
    static var MousePosition: Point { return CursorT.Position }
    // instance mirrors (so `MouseButtons.Left` / `ModifierKeys` work unqualified inside subclasses)
    var MouseButtons: MouseButtons { return Control.MouseButtons }
    var ModifierKeys: Keys { return Control.ModifierKeys }
    var MousePosition: Point { return Control.MousePosition }

    // ---- geometry
    var Left: Int { get { return _x } set { SetBounds(newValue, _y, _w, _h) } }
    var Top: Int { get { return _y } set { SetBounds(_x, newValue, _w, _h) } }
    var Width: Int { get { return _w } set { SetBounds(_x, _y, newValue, _h) } }
    var Height: Int { get { return _h } set { SetBounds(_x, _y, _w, newValue) } }
    var Right: Int { return _x + _w }
    var Bottom: Int { return _y + _h }
    var Location: Point { get { return PointT(_x, _y) } set { SetBounds(newValue.X, newValue.Y, _w, _h) } }
    var Size: SizeT { get { return SizeT(_w, _h) } set { SetBounds(_x, _y, newValue.Width, newValue.Height) } }
    var Bounds: Rectangle { get { return RectangleT(_x, _y, _w, _h) } set { SetBounds(newValue.X, newValue.Y, newValue.Width, newValue.Height) } }
    var ClientSize: SizeT { get { return SizeT(_w, _h) } set { SetBounds(_x, _y, newValue.Width, newValue.Height) } }
    var ClientRectangle: Rectangle { let c = ClientSize; return RectangleT(0, 0, c.Width, c.Height) }
    func SetBounds(_ x: Int, _ y: Int, _ w: Int, _ h: Int) {
        _x = x; _y = y; _w = max(0, w); _h = max(0, h)
        _applyBounds()
    }

    // ---- appearance
    var Text: String { get { return _text } set { if _text != newValue { _text = newValue; _textChanged() } } }
    var Font: FontT {
        get { return _font ?? Parent?.Font ?? Control.DefaultFont }
        set { _font = newValue; _styleChanged() }
    }
    static let DefaultFont: FontT = FontT("Microsoft JhengHei UI", 9)
    var ForeColor: Color { get { return _foreColor ?? Parent?.ForeColor ?? Color.FromArgb(0, 0, 0) } set { _foreColor = newValue; _styleChanged() } }
    var BackColor: Color { get { return _backColor ?? Parent?.BackColor ?? Color.FromArgb(0xF0, 0xF0, 0xF0) } set { _backColor = newValue; _styleChanged() } }
    var Enabled: Bool { get { return _enabled } set { _enabled = newValue; _styleChanged() } }

    // ---- visibility (Visible setter routes through the overridable SetVisibleCore like WinForms)
    var Visible: Bool { get { return _visible } set { SetVisibleCore(newValue) } }
    func SetVisibleCore(_ value: Bool) { _visible = value; _nsView?.isHidden = !value }
    func Show() { Visible = true }
    func Hide() { Visible = false }
    func SetStyle(_ s: ControlStyles, _ on: Bool) { }
    func UpdateStyles() { }
    func SuspendLayout() { }
    func ResumeLayout() { }
    func ResumeLayout(_ b: Bool) { }
    func PerformLayout() { }

    var IsDisposed: Bool { return _disposed }
    var Disposing: Bool { return false }
    func Dispose() { _disposed = true; _nsView?.removeFromSuperview() }

    // ---- painting / threading
    func Invalidate() { _Coords.onMain { [weak self] in self?._nsView?.needsDisplay = true } }
    func Invalidate(_ r: Rectangle) { Invalidate() }
    func Refresh() { Invalidate(); if Foundation.Thread.isMainThread { _nsView?.displayIfNeeded() } }
    func Update() { if Foundation.Thread.isMainThread { _nsView?.displayIfNeeded() } }
    func BeginInvoke(_ a: @escaping () -> Void) { DispatchQueue.main.async(execute: a) }
    func Invoke(_ a: @escaping () -> Void) { if Foundation.Thread.isMainThread { a() } else { DispatchQueue.main.sync(execute: a) } }
    var InvokeRequired: Bool { return !Foundation.Thread.isMainThread }
    var Handle: IntPtr { return 0 }
    var IsHandleCreated: Bool { return _nsView != nil }
    var Focused: Bool { return false }
    @discardableResult func Focus() -> Bool { return false }
    func Select() { _ = Focus() }
    func BringToFront() { }
    func SendToBack() { }
    func PointToScreen(_ p: Point) -> Point {
        var x = p.X, y = p.Y
        var c: Control? = self
        while let cc = c { if cc is Form { let cl = (cc as! Form)._clientOrigin(); x += cl.0; y += cl.1; break }; x += cc._x; y += cc._y; c = cc.Parent }
        return PointT(x, y)
    }
    func PointToClient(_ p: Point) -> Point {
        let o = PointToScreen(PointT(0, 0))
        return PointT(p.X - o.X, p.Y - o.Y)
    }

    // ---- overridable events
    func OnPaint(_ e: PaintEventArgs) { Paint?(e) }
    func OnPaintBackground(_ e: PaintEventArgs) { e.Graphics.Clear(BackColor) }
    func OnMouseDown(_ e: MouseEventArgs) { MouseDown?(e) }
    func OnMouseUp(_ e: MouseEventArgs) { MouseUp?(e) }
    func OnMouseMove(_ e: MouseEventArgs) { MouseMove?(e) }
    func OnMouseClick(_ e: MouseEventArgs) { MouseClick?(e) }
    func OnMouseDoubleClick(_ e: MouseEventArgs) { }
    func OnMouseWheel(_ e: MouseEventArgs) { MouseWheel?(e) }
    func OnMouseEnter(_ e: EventArgs) { MouseEnter?() }
    func OnMouseLeave(_ e: EventArgs) { MouseLeave?() }
    func OnClick(_ e: EventArgs) { Click?() }
    func OnKeyDown(_ e: KeyEventArgs) { KeyDown?(e) }
    func OnKeyUp(_ e: KeyEventArgs) { KeyUp?(e) }
    func OnTextChanged(_ e: EventArgs) { TextChanged?() }
    func OnResize(_ e: EventArgs) { Resize?() }
    func OnVisibleChanged(_ e: EventArgs) { VisibleChanged?() }

    // ---- events (C# `x += delegate { }` → `x = { }`; handlers with (sender, e) take just `e`)
    var Paint: ((PaintEventArgs) -> Void)? = nil
    var MouseDown: ((MouseEventArgs) -> Void)? = nil
    var MouseUp: ((MouseEventArgs) -> Void)? = nil
    var MouseMove: ((MouseEventArgs) -> Void)? = nil
    var MouseClick: ((MouseEventArgs) -> Void)? = nil
    var MouseWheel: ((MouseEventArgs) -> Void)? = nil
    var MouseEnter: (() -> Void)? = nil
    var MouseLeave: (() -> Void)? = nil
    var Click: (() -> Void)? = nil
    var KeyDown: ((KeyEventArgs) -> Void)? = nil
    var KeyUp: ((KeyEventArgs) -> Void)? = nil
    var TextChanged: (() -> Void)? = nil
    var Resize: (() -> Void)? = nil
    var VisibleChanged: (() -> Void)? = nil

    // ---- mac internals
    var _nsView: NSView? { return nil }
    func _applyBounds() { _nsView?.frame = NSRect(x: CGFloat(_x), y: CGFloat(_y), width: CGFloat(_w), height: CGFloat(_h)) }
    func _textChanged() { _autoSize(); OnTextChanged(EventArgs.Empty) }
    func _styleChanged() { for c in Controls { c._styleChanged() } }
    func _autoSize() { }
    func _cursorChanged() { }
    func _childAdded(_ c: Control) { }
    func _hostView() -> NSView? { return _nsView }
    func _create() { }   // child controls build their NSView lazily (when added to a form)
}
typealias MouseButtonsT = MouseButtons

// ---------------------------------------------------------------- Form

final class FormPanel: NSPanel {
    weak var form: Form?
    var allowKey = false
    override var canBecomeKey: Bool { return allowKey }
    override var canBecomeMain: Bool { return allowKey }

    // KeyPreview / AcceptButton / CancelButton (skip while an input method is composing — 注音/速成 use Enter/Esc)
    override func sendEvent(_ event: NSEvent) {
        if event.type == .keyDown, let f = form, allowKey {
            var composing = false
            if let tv = firstResponder as? NSTextView, tv.hasMarkedText() { composing = true }
            if !composing {
                let kc = Keys.FromEvent(event)
                if f.KeyPreview {
                    let e = KeyEventArgs(kc | Keys.ModsFrom(event.modifierFlags))
                    f.OnKeyDown(e)
                    if e.Handled { return }
                }
                if kc == Keys.Enter, let b = f.AcceptButton { b.PerformClick(); return }
                if kc == Keys.Escape, let b = f.CancelButton { b.PerformClick(); return }
            }
        }
        super.sendEvent(event)
    }
}

final class FormWindowDelegate: NSObject, NSWindowDelegate {
    weak var form: Form?
    func windowShouldClose(_ sender: NSWindow) -> Bool {
        guard let f = form else { return true }
        let e = FormClosingEventArgs(.UserClosing, false)
        f.OnFormClosing(e)
        if e.Cancel { return false }
        f._closedByUser()
        return false   // we close ourselves (keeps panel alive for IsDisposed bookkeeping)
    }
    func windowDidMove(_ notification: Notification) { form?._syncFromWindow() }
    func windowDidResize(_ notification: Notification) { form?._syncFromWindow() }
    // WinForms Activated / Deactivate（mac：視窗拿到／失去鍵盤焦點）
    func windowDidBecomeKey(_ notification: Notification) { form?.Activated?() }
    func windowDidResignKey(_ notification: Notification) { form?.Deactivate?() }
}

final class FormView: NSView {
    weak var form: Form?
    var tracking: NSTrackingArea? = nil
    var presented: CGImage? = nil
    var presentedScale: CGFloat = 1
    var ctrlRight = false

    override var isFlipped: Bool { return true }
    override var isOpaque: Bool { return false }
    override func acceptsFirstMouse(for event: NSEvent?) -> Bool { return true }
    override var wantsUpdateLayer: Bool { return presented != nil }
    override func updateLayer() {
        guard let l = layer, let img = presented else { return }
        l.contents = img
        l.contentsScale = presentedScale
        l.contentsGravity = .topLeft
        l.magnificationFilter = .nearest
    }

    override func draw(_ dirtyRect: NSRect) {
        guard let f = form, let ctx = NSGraphicsContext.current?.cgContext else { return }
        ctx.clear(bounds)
        if presented != nil { return }
        let w = Int(bounds.width.rounded()), h = Int(bounds.height.rounded())
        guard let g = _formsGraphics(ctx, w, h) else { return }
        let e = PaintEventArgs(g, RectangleT(0, 0, w, h))
        f.OnPaintBackground(e)
        f.OnPaint(e)
    }

    override func updateTrackingAreas() {
        if let t = tracking { removeTrackingArea(t) }
        let t = NSTrackingArea(rect: .zero, options: [.mouseEnteredAndExited, .mouseMoved, .activeAlways, .inVisibleRect, .cursorUpdate], owner: self, userInfo: nil)
        addTrackingArea(t)
        tracking = t
        super.updateTrackingAreas()
    }

    func args(_ e: NSEvent, _ b: MouseButtons, _ delta: Int = 0) -> MouseEventArgs {
        let p = convert(e.locationInWindow, from: nil)
        let clicks = (e.type == .mouseMoved || e.type == .scrollWheel || e.type == .leftMouseDragged || e.type == .rightMouseDragged) ? 0 : e.clickCount
        return MouseEventArgs(b, clicks, Int(p.x.rounded(.down)), Int(p.y.rounded(.down)), delta)
    }

    override func mouseDown(with e: NSEvent) {
        guard let f = form else { return }
        // mac: Control+click = right click (trackpads without a secondary click setting)
        ctrlRight = e.modifierFlags.contains(.control)
        f._cursorSet()
        f.OnMouseDown(args(e, ctrlRight ? MouseButtons.Right : MouseButtons.Left))
    }
    override func mouseUp(with e: NSEvent) {
        guard let f = form else { return }
        let b = ctrlRight ? MouseButtons.Right : MouseButtons.Left
        ctrlRight = false
        let a = args(e, b)
        f.OnMouseUp(a)
        if a.X >= 0 && a.Y >= 0 && a.X < f.ClientSize.Width && a.Y < f.ClientSize.Height {
            f.OnClick(EventArgs.Empty)
            f.OnMouseClick(a)
        }
    }
    override func mouseDragged(with e: NSEvent) { form?.OnMouseMove(args(e, ctrlRight ? MouseButtons.Right : MouseButtons.Left)) }
    override func rightMouseDown(with e: NSEvent) { form?.OnMouseDown(args(e, MouseButtons.Right)) }
    override func rightMouseUp(with e: NSEvent) {
        guard let f = form else { return }
        let a = args(e, MouseButtons.Right)
        f.OnMouseUp(a)
        f.OnMouseClick(a)
    }
    override func rightMouseDragged(with e: NSEvent) { form?.OnMouseMove(args(e, MouseButtons.Right)) }
    override func otherMouseDown(with e: NSEvent) { form?.OnMouseDown(args(e, e.buttonNumber == 2 ? MouseButtons.Middle : MouseButtons.XButton1)) }
    override func otherMouseUp(with e: NSEvent) { form?.OnMouseUp(args(e, e.buttonNumber == 2 ? MouseButtons.Middle : MouseButtons.XButton1)) }
    override func mouseMoved(with e: NSEvent) { form?._cursorSet(); form?.OnMouseMove(args(e, MouseButtons.None)) }
    override func mouseEntered(with e: NSEvent) { form?._cursorSet(); form?.OnMouseEnter(EventArgs.Empty) }
    override func mouseExited(with e: NSEvent) { NSCursor.arrow.set(); form?.OnMouseLeave(EventArgs.Empty) }
    override func cursorUpdate(with e: NSEvent) { form?._cursorSet() }
    override func scrollWheel(with e: NSEvent) {
        let d = Int((e.scrollingDeltaY * (e.hasPreciseScrollingDeltas ? 4 : 40)).rounded())
        form?.OnMouseWheel(args(e, MouseButtons.None, d))
    }
    // drag & drop（Form.AllowDrop／DragEnter／DragDrop：04_shim_custom_b.swift）
    override func draggingEntered(_ sender: NSDraggingInfo) -> NSDragOperation { return form?._dragEntered(sender) ?? [] }
    override func performDragOperation(_ sender: NSDraggingInfo) -> Bool { return form?._performDrag(sender) ?? false }
}

class Form: Control {
    var panel: FormPanel? = nil
    var view: FormView? = nil
    var winDelegate: FormWindowDelegate? = nil
    var _handleCreated = false
    var _shownOnce = false
    var _visibleFlag = false
    var _opacity = 1.0
    var _transparencyKey: Color? = nil
    var _borderStyle = FormBorderStyleT.Sizable

    var StartPosition = FormStartPosition.WindowsDefaultLocation
    var ShowInTaskbar = true
    var TopMost = false { didSet { _applyLevel() } }
    var MaximizeBox = true
    var MinimizeBox = true
    var ControlBox = true
    var KeyPreview = false
    var AutoScaleMode = AutoScaleModeT.Font
    var AutoScaleDimensions = SizeT(0, 0)
    var WindowState = FormWindowState.Normal
    var DialogResult = DialogResultT.None
    var AcceptButton: Button? = nil
    var CancelButton: Button? = nil
    var Owner: Form? = nil
    var Icon: Any? = nil
    var DoubleBuffered = true

    // events (C# `FormClosing += delegate(object s, FormClosingEventArgs e) {…}` → `FormClosing = { e in … }`)
    var FormClosing: ((FormClosingEventArgs) -> Void)? = nil
    var FormClosed: (() -> Void)? = nil
    var Shown: (() -> Void)? = nil
    var Load: (() -> Void)? = nil
    var Activated: (() -> Void)? = nil
    var Deactivate: (() -> Void)? = nil

    override init() {
        super.init()
        _w = 300; _h = 300
        _visible = false
    }

    // ---- registry handle → form (for W.*)
    static var _registry: [Int: WeakForm] = [:]
    final class WeakForm { weak var f: Form?; init(_ f: Form) { self.f = f } }
    static func _FromHandle(_ h: IntPtr) -> Form? { return h == 0 ? nil : _registry[h]?.f }
    static var _all: [Form] { return _registry.values.compactMap { $0.f } }

    // ---- border style / overlay-ness
    var FormBorderStyle: FormBorderStyleT {
        get { return _borderStyle }
        set {
            let cs = ClientSize
            _borderStyle = newValue
            if panel == nil { ClientSize = cs }
        }
    }
    var _isDialog: Bool { return _borderStyle != FormBorderStyleT.None }
    // overridable by OverlayForm
    var ShowWithoutActivation: Bool { return false }
    var _wantsClickThrough: Bool { return false }
    var _overlayLevel: NSWindow.Level { return .statusBar }
    // borderless overlay that may become key without activating the app (C#: CreateParams without WS_EX_NOACTIVATE,
    // e.g. the pixel popup menu: gets Esc / arrow keys, Deactivate fires when it loses focus)
    var _overlayKeyable: Bool { return false }

    var _styleMask: NSWindow.StyleMask {
        if !_isDialog { return [.borderless, .nonactivatingPanel] }
        // mac: dialogs are titled panels that can become key even while another app stays active (no activation needed to type)
        var m: NSWindow.StyleMask = [.titled, .closable, .nonactivatingPanel]
        if _borderStyle == FormBorderStyleT.FixedToolWindow || _borderStyle == FormBorderStyleT.SizableToolWindow { m.insert(.utilityWindow) }
        if _borderStyle == FormBorderStyleT.Sizable || _borderStyle == FormBorderStyleT.SizableToolWindow { m.insert(.resizable) }
        if MinimizeBox && !m.contains(.utilityWindow) { m.insert(.miniaturizable) }
        return m
    }

    // client area ↔ outer frame (dialogs have a title bar)
    override var ClientSize: SizeT {
        get {
            if !_isDialog { return SizeT(_w, _h) }
            let c = NSWindow.contentRect(forFrameRect: NSRect(x: 0, y: 0, width: _w, height: _h), styleMask: _styleMask)
            return SizeT(Int(c.width.rounded()), Int(c.height.rounded()))
        }
        set {
            if !_isDialog { SetBounds(_x, _y, newValue.Width, newValue.Height); return }
            let fr = NSWindow.frameRect(forContentRect: NSRect(x: 0, y: 0, width: newValue.Width, height: newValue.Height), styleMask: _styleMask)
            SetBounds(_x, _y, Int(fr.width.rounded()), Int(fr.height.rounded()))
        }
    }
    func _clientOrigin() -> (Int, Int) {
        if !_isDialog { return (_x, _y) }
        let cs = ClientSize
        return (_x + (_w - cs.Width) / 2, _y + (_h - cs.Height))
    }

    // ---- window creation
    override var Handle: IntPtr { _ensure(); return panel?.windowNumber ?? 0 }
    override var IsHandleCreated: Bool { return _handleCreated && !_disposed }
    override var _nsView: NSView? { return view }
    override func _hostView() -> NSView? { return view }

    func _ensure() {
        if panel != nil || _disposed { return }
        if !Foundation.Thread.isMainThread { DispatchQueue.main.sync { self._ensure() }; return }
        let frame = _Coords.toCocoa(_x, _y, max(1, _w), max(1, _h))
        let p = FormPanel(contentRect: NSWindow.contentRect(forFrameRect: frame, styleMask: _styleMask), styleMask: _styleMask, backing: .buffered, defer: false)
        p.form = self
        p.isReleasedWhenClosed = false
        p.hidesOnDeactivate = false
        p.isMovableByWindowBackground = false
        p.animationBehavior = .none
        if _isDialog {
            p.allowKey = true
            p.becomesKeyOnlyIfNeeded = false
            p.isFloatingPanel = false
            p.title = _text
            p.backgroundColor = _formsNSColor(BackColor)
            p.collectionBehavior = [.moveToActiveSpace, .fullScreenAuxiliary]
            p.hasShadow = true
            p.appearance = NSAppearance(named: .aqua)   // C# dialogs are light (cream background, black text)
        } else {
            p.allowKey = _overlayKeyable
            p.becomesKeyOnlyIfNeeded = !_overlayKeyable
            p.backgroundColor = .clear
            p.isOpaque = false
            p.hasShadow = false
            p.collectionBehavior = [.canJoinAllSpaces, .stationary, .ignoresCycle, .fullScreenAuxiliary]
            p.ignoresMouseEvents = _wantsClickThrough
        }
        let v = FormView(frame: NSRect(origin: .zero, size: p.contentRect(forFrameRect: p.frame).size))
        v.form = self
        v.wantsLayer = true
        v.layerContentsRedrawPolicy = .onSetNeedsDisplay
        v.autoresizingMask = [.width, .height]
        p.contentView = v
        p.acceptsMouseMovedEvents = true
        let d = FormWindowDelegate()
        d.form = self
        p.delegate = d
        winDelegate = d
        panel = p
        view = v
        p.alphaValue = CGFloat(_opacity)
        p.setFrame(frame, display: false)
        _applyLevel()
        for c in Controls { _attach(c) }
        _handleCreated = true
        Form._registry[p.windowNumber] = WeakForm(self)
    }

    func _applyLevel() {
        guard let p = panel else { return }
        if _isDialog { p.level = TopMost ? .floating : .normal } else { p.level = _overlayLevel }   // set last (other props reset level)
    }

    func _attach(_ c: Control) {
        guard let v = view, let cv = c._nsView else { return }
        if cv.superview !== v { v.addSubview(cv) }
        c._applyBounds()
        c._styleChanged()
    }
    override func _childAdded(_ c: Control) { c._create(); _attach(c) }

    override func _applyBounds() {
        guard let p = panel else { return }
        let fr = _Coords.toCocoa(_x, _y, max(1, _w), max(1, _h))
        if p.frame != fr { p.setFrame(fr, display: _visibleFlag) }
        view?.needsDisplay = true
    }
    func _syncFromWindow() {
        guard let p = panel else { return }
        let r = _Coords.fromCocoa(p.frame)
        _x = r.0; _y = r.1; _w = r.2; _h = r.3
    }

    override func _textChanged() { panel?.title = _text; super._textChanged() }
    override func _styleChanged() {
        if let p = panel, _isDialog { p.backgroundColor = _formsNSColor(BackColor) }
        view?.needsDisplay = true
        super._styleChanged()
    }
    override func _cursorChanged() { }
    func _cursorSet() { (Cursor ?? Cursors.Default).ns.set() }

    // ---- opacity / transparency
    var Opacity: Double {
        get { return _opacity }
        set { _opacity = max(0, min(1, newValue)); _Coords.onMain { [weak self] in if let s = self { s.panel?.alphaValue = CGFloat(s._opacity) } } }
    }
    var TransparencyKey: Color {
        get { return _transparencyKey ?? Color.Empty }
        set { _transparencyKey = newValue; view?.needsDisplay = true }
    }
    var AllowTransparency = true

    // ---- visibility
    override var Visible: Bool { get { return _visibleFlag } set { SetVisibleCore(newValue) } }
    override func SetVisibleCore(_ value: Bool) {
        if !Foundation.Thread.isMainThread { DispatchQueue.main.async { self.SetVisibleCore(value) }; return }
        if _disposed { return }
        let was = _visibleFlag
        _visibleFlag = value
        _visible = value
        if value {
            _ensure()
            guard let p = panel else { return }
            if !_shownOnce && StartPosition == .CenterScreen {
                let wa = Screen.FromPoint(CursorT.Position).WorkingArea
                SetBounds(wa.X + (wa.Width - _w) / 2, wa.Y + (wa.Height - _h) / 2, _w, _h)
            }
            _applyBounds()
            if (_isDialog || _overlayKeyable) && !ShowWithoutActivation {
                p.makeKeyAndOrderFront(nil)   // nonactivating panel: becomes key without activating the app
                p.orderFrontRegardless()
            } else {
                p.orderFrontRegardless()
            }
            view?.needsDisplay = true
            if !_shownOnce {
                _shownOnce = true
                Load?()
                DispatchQueue.main.async { [weak self] in self?.OnShown(EventArgs.Empty) }
            }
        } else {
            panel?.orderOut(nil)
            if _isDialog { Form._maybeDeactivate() }
        }
        if was != value { OnVisibleChanged(EventArgs.Empty) }
    }
    func OnShown(_ e: EventArgs) { Shown?() }
    func OnFormClosing(_ e: FormClosingEventArgs) { FormClosing?(e) }
    func OnFormClosed(_ e: EventArgs) { FormClosed?() }
    func OnLoad(_ e: EventArgs) { Load?() }
    // C# WndProc(ref Message m) — on mac only W.RegisterHotKey delivers WM_HOTKEY (0x0312) here
    func WndProc(_ m: inout Message) { }
    func DefWndProc(_ m: inout Message) { }

    func _activateApp() {
        if #available(macOS 14.0, *) { NSApp.activate() } else { NSApp.activate(ignoringOtherApps: true) }
    }
    // a dialog went away: give focus back to whoever was before (we're an accessory app)
    static func _maybeDeactivate() {
        DispatchQueue.main.async {
            for f in Form._all where f._isDialog && f._visibleFlag { return }
            if NSApp.isActive { NSApp.deactivate() }
        }
    }

    func Activate() {
        _ensure()
        guard let p = panel else { return }
        if _isDialog || _overlayKeyable { p.makeKeyAndOrderFront(nil); p.orderFrontRegardless() } else { p.orderFrontRegardless() }
    }
    override func BringToFront() { panel?.orderFrontRegardless() }
    override func SendToBack() { panel?.orderBack(nil) }
    override var Focused: Bool { return panel?.isKeyWindow ?? false }
    @discardableResult override func Focus() -> Bool {
        guard let p = panel, _isDialog else { return false }
        p.makeKey()
        return p.isKeyWindow
    }
    var ContainsFocus: Bool { return Focused }

    func Close() {
        if _disposed { return }
        let e = FormClosingEventArgs(.UserClosing, false)
        OnFormClosing(e)
        if e.Cancel { return }
        _closedByUser()
    }
    func _closedByUser() {
        _visibleFlag = false; _visible = false
        if let p = panel {
            p.orderOut(nil)
            Form._registry.removeValue(forKey: p.windowNumber)
            p.delegate = nil
            p.close()
        }
        _disposed = true
        OnFormClosed(EventArgs.Empty)
        if _isDialog { Form._maybeDeactivate() }
    }
    override func Dispose() {
        if _disposed { return }
        if let p = panel { p.orderOut(nil); Form._registry.removeValue(forKey: p.windowNumber); p.delegate = nil; p.close() }
        _visibleFlag = false; _visible = false
        _disposed = true
    }

    // modal dialog (NSApp.runModal)
    @discardableResult func ShowDialog() -> DialogResultT {
        _ensure()
        guard let p = panel else { return .Cancel }
        DialogResult = .None
        Visible = true
        _modal = true
        NSApp.runModal(for: p)
        _modal = false
        Visible = false
        return DialogResult == .None ? .Cancel : DialogResult
    }
    var _modal = false
    func _endModalIfNeeded() { if _modal { NSApp.stopModal() } }

    // ---- per-pixel present (used by W.Present): image + move/resize in one CA transaction
    func _present(_ img: CGImage?, _ scale: CGFloat, _ x: Int, _ y: Int, _ w: Int, _ h: Int) {
        _ensure()
        guard let p = panel, let v = view else { return }
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        v.presented = img
        v.presentedScale = scale
        _x = x; _y = y; _w = max(1, w); _h = max(1, h)
        let fr = _Coords.toCocoa(_x, _y, _w, _h)
        if p.frame != fr { p.setFrame(fr, display: false) }
        if let l = v.layer {
            l.contents = img
            l.contentsScale = scale
            l.contentsGravity = .topLeft
            l.magnificationFilter = .nearest
        }
        CATransaction.commit()
    }
}
typealias FormBorderStyleT = FormBorderStyle
typealias AutoScaleModeT = AutoScaleMode
typealias DialogResultT = DialogResult

// ---------------------------------------------------------------- dialog controls (real AppKit views)

final class _ControlTarget: NSObject, NSTextFieldDelegate {
    weak var c: Control?
    init(_ c: Control) { self.c = c }
    @objc func fire(_ sender: Any?) { (c as? Button)?.PerformClick(); (c as? RadioButton)?._clicked(); (c as? CheckBox)?._clicked() }
    func controlTextDidChange(_ obj: Notification) { (c as? TextBox)?._userEdited() }
    @objc func dateChanged(_ sender: Any?) { (c as? DateTimePicker)?.ValueChanged?() }
}

class Label: Control {
    var tf: NSTextField? = nil
    var TextAlign = ContentAlignment.TopLeft
    override init() { super.init(); _w = 100; _h = 23 }
    override var _nsView: NSView? { return tf }
    override func _create() {
        if tf != nil { return }
        let t = NSTextField(labelWithString: _text)
        t.isBezeled = false; t.drawsBackground = false; t.isEditable = false; t.isSelectable = false
        t.lineBreakMode = .byWordWrapping
        tf = t
    }
    override func _styleChanged() {
        guard let t = tf else { return }
        t.font = _formsNSFont(Font)
        t.textColor = _formsNSColor(ForeColor)
        t.isEnabled = Enabled
        _autoSize()
    }
    override func _textChanged() { tf?.stringValue = _text; super._textChanged() }
    override func _autoSize() {
        guard AutoSize else { return }
        if let t = tf {
            let s = t.fittingSize
            _w = Int(ceil(s.width)) + 1; _h = Int(ceil(s.height))
        } else {
            let s = (_text as NSString).size(withAttributes: [.font: _formsNSFont(Font)])
            _w = Int(ceil(s.width)) + 6; _h = Int(ceil(s.height)) + 2
        }
        _applyBounds()
    }
}

class TextBox: Control {
    var tf: NSTextField? = nil
    var target: _ControlTarget? = nil
    var Multiline = false
    var ReadOnly = false { didSet { tf?.isEditable = !ReadOnly } }
    var MaxLength = 32767
    var PlaceholderText = "" { didSet { tf?.placeholderString = PlaceholderText } }
    var UseSystemPasswordChar = false
    override init() { super.init(); _w = 100; _h = 24 }
    override var _nsView: NSView? { return tf }
    override func _create() {
        if tf != nil { return }
        let t = NSTextField(string: _text)
        t.isBezeled = true; t.bezelStyle = .squareBezel; t.isEditable = !ReadOnly; t.isSelectable = true
        t.usesSingleLineMode = !Multiline
        t.cell?.isScrollable = true
        t.cell?.wraps = false
        let tg = _ControlTarget(self)
        t.delegate = tg
        target = tg
        tf = t
    }
    override func _styleChanged() {
        guard let t = tf else { return }
        t.font = _formsNSFont(Font)
        t.textColor = _formsNSColor(ForeColor)
        t.isEnabled = Enabled
    }
    override var Text: String {
        get { if let t = tf { _text = t.stringValue }; return _text }
        set { let old = Text; _text = newValue; tf?.stringValue = newValue; if old != newValue { OnTextChanged(EventArgs.Empty) } }
    }
    func _userEdited() { _text = tf?.stringValue ?? _text; OnTextChanged(EventArgs.Empty) }
    @discardableResult override func Focus() -> Bool {
        guard let t = tf, let w = t.window else { return false }
        return w.makeFirstResponder(t)
    }
    override func Select() { _ = Focus(); tf?.currentEditor()?.selectAll(nil) }
    func SelectAll() { tf?.currentEditor()?.selectAll(nil) }
    func Clear() { Text = "" }
    override var Focused: Bool { guard let t = tf, let ed = t.currentEditor() else { return false }; return t.window?.firstResponder === ed }
}

final class FlatButtonAppearance {
    weak var owner: Button?
    var BorderColor: Color = Color.Empty { didSet { owner?._styleChanged() } }
    var BorderSize = 1 { didSet { owner?._styleChanged() } }
    var MouseOverBackColor: Color = Color.Empty
    var MouseDownBackColor: Color = Color.Empty
}

class Button: Control {
    var bt: NSButton? = nil
    var target: _ControlTarget? = nil
    let FlatAppearance = FlatButtonAppearance()
    var FlatStyle = FlatStyleT.Standard { didSet { _styleChanged() } }
    var UseVisualStyleBackColor = true
    var DialogResult = DialogResultT.None
    override init() { super.init(); _w = 75; _h = 23; FlatAppearance.owner = self }
    override var _nsView: NSView? { return bt }
    override func _create() {
        if bt != nil { return }
        let tg = _ControlTarget(self)
        let b = NSButton(title: _text, target: tg, action: #selector(_ControlTarget.fire(_:)))
        b.bezelStyle = .rounded
        b.wantsLayer = true
        target = tg
        bt = b
    }
    override func _textChanged() { super._textChanged(); _styleChanged() }
    override func _styleChanged() {
        guard let b = bt else { return }
        b.isEnabled = Enabled
        let font = _formsNSFont(Font)
        let para = NSMutableParagraphStyle(); para.alignment = .center
        b.attributedTitle = NSAttributedString(string: _text, attributes: [.font: font, .foregroundColor: _formsNSColor(ForeColor), .paragraphStyle: para])
        if FlatStyle == .Flat || FlatStyle == .Popup {
            b.isBordered = false
            b.layer?.backgroundColor = _formsNSColor(BackColor).cgColor
            b.layer?.cornerRadius = 0
            let bc = FlatAppearance.BorderColor
            b.layer?.borderWidth = CGFloat(FlatAppearance.BorderSize)
            b.layer?.borderColor = (bc == Color.Empty ? NSColor.darkGray : _formsNSColor(bc)).cgColor
        } else {
            b.isBordered = true
            b.bezelStyle = .rounded
            b.layer?.backgroundColor = nil
            b.layer?.borderWidth = 0
        }
    }
    func PerformClick() {
        if !Enabled { return }
        OnClick(EventArgs.Empty)
        if DialogResult != .None, let f = _form() { f.DialogResult = DialogResult; f._endModalIfNeeded() }
    }
    func _form() -> Form? { var c: Control? = Parent; while let cc = c { if let f = cc as? Form { return f }; c = cc.Parent }; return nil }
    @discardableResult override func Focus() -> Bool { guard let b = bt, let w = b.window else { return false }; return w.makeFirstResponder(b) }
}
typealias FlatStyleT = FlatStyle

class RadioButton: Control {
    var bt: NSButton? = nil
    var target: _ControlTarget? = nil
    var _checked = false
    var CheckedChanged: (() -> Void)? = nil
    var AutoCheck = true
    override init() { super.init(); _w = 104; _h = 24 }
    override var _nsView: NSView? { return bt }
    override func _create() {
        if bt != nil { return }
        let tg = _ControlTarget(self)
        let b = NSButton(radioButtonWithTitle: _text, target: tg, action: #selector(_ControlTarget.fire(_:)))
        b.state = _checked ? .on : .off
        target = tg
        bt = b
    }
    var Checked: Bool {
        get { return _checked }
        set {
            if _checked == newValue { bt?.state = newValue ? .on : .off; return }
            _checked = newValue
            bt?.state = newValue ? .on : .off
            if newValue, let p = Parent { for c in p.Controls { if let r = c as? RadioButton, r !== self, r._checked { r.Checked = false } } }
            CheckedChanged?()
        }
    }
    func _clicked() { if AutoCheck { Checked = true } else { bt?.state = _checked ? .on : .off }; OnClick(EventArgs.Empty) }
    func PerformClick() { _clicked() }
    override func _textChanged() { bt?.title = _text; super._textChanged(); _styleChanged() }
    override func _styleChanged() {
        guard let b = bt else { return }
        b.isEnabled = Enabled
        b.attributedTitle = NSAttributedString(string: _text, attributes: [.font: _formsNSFont(Font), .foregroundColor: _formsNSColor(ForeColor)])
        _autoSize()
    }
    override func _autoSize() {
        guard AutoSize, let b = bt else { return }
        let s = b.fittingSize
        _w = Int(ceil(s.width)) + 2; _h = max(_h, Int(ceil(s.height)))
        _applyBounds()
    }
}

class CheckBox: Control {
    var bt: NSButton? = nil
    var target: _ControlTarget? = nil
    var _checked = false
    var CheckedChanged: (() -> Void)? = nil
    override init() { super.init(); _w = 104; _h = 24 }
    override var _nsView: NSView? { return bt }
    override func _create() {
        if bt != nil { return }
        let tg = _ControlTarget(self)
        let b = NSButton(checkboxWithTitle: _text, target: tg, action: #selector(_ControlTarget.fire(_:)))
        b.state = _checked ? .on : .off
        target = tg
        bt = b
    }
    var Checked: Bool {
        get { return _checked }
        set { let ch = _checked != newValue; _checked = newValue; bt?.state = newValue ? .on : .off; if ch { CheckedChanged?() } }
    }
    func _clicked() { Checked = bt?.state == .on; OnClick(EventArgs.Empty) }
    override func _styleChanged() {
        guard let b = bt else { return }
        b.isEnabled = Enabled
        b.attributedTitle = NSAttributedString(string: _text, attributes: [.font: _formsNSFont(Font), .foregroundColor: _formsNSColor(ForeColor)])
        if AutoSize { let s = b.fittingSize; _w = Int(ceil(s.width)) + 2; _applyBounds() }
    }
}

class Panel: Control {
    final class FlippedView: NSView { override var isFlipped: Bool { return true } }
    var pv: FlippedView? = nil
    override var _nsView: NSView? { return pv }
    override func _create() {
        if pv != nil { return }
        let v = FlippedView(); v.wantsLayer = true
        pv = v
        for c in Controls { c._create(); if let cv = c._nsView { v.addSubview(cv) }; c._applyBounds(); c._styleChanged() }
    }
    override func _childAdded(_ c: Control) {
        c._create()
        if let v = pv, let cv = c._nsView { v.addSubview(cv); c._applyBounds(); c._styleChanged() }
    }
    override func _styleChanged() {
        if let b = _backColor { pv?.layer?.backgroundColor = _formsNSColor(b).cgColor }
        super._styleChanged()
    }
}

class DateTimePicker: Control {
    var dp: NSDatePicker? = nil
    var target: _ControlTarget? = nil
    var Format = DateTimePickerFormat.Long
    var CustomFormat = ""
    var ShowUpDown = false
    var ValueChanged: (() -> Void)? = nil
    var _date = Date()
    override init() { super.init(); _w = 200; _h = 24 }
    override var _nsView: NSView? { return dp }
    override func _create() {
        if dp != nil { return }
        let d = NSDatePicker()
        d.datePickerStyle = .textFieldAndStepper
        d.datePickerElements = .yearMonthDay
        d.dateValue = _date
        d.isBezeled = true
        let tg = _ControlTarget(self)
        d.target = tg
        d.action = #selector(_ControlTarget.dateChanged(_:))
        target = tg
        dp = d
    }
    override func _styleChanged() {
        guard let d = dp else { return }
        d.font = _formsNSFont(Font)
        d.isEnabled = Enabled
        d.datePickerElements = (Format == .Time) ? .hourMinuteSecond : (CustomFormat.contains("H") || CustomFormat.contains("m") && CustomFormat.contains(":") ? [.yearMonthDay, .hourMinute] : .yearMonthDay)
    }
    // Value as compat DateTime (local time)
    var Value: DateTime {
        get {
            let d = dp?.dateValue ?? _date
            let c = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute, .second], from: d)
            return DateTime(c.year ?? 2000, c.month ?? 1, c.day ?? 1, c.hour ?? 0, c.minute ?? 0, c.second ?? 0)
        }
        set {
            var c = DateComponents()
            c.year = newValue.Year; c.month = newValue.Month; c.day = newValue.Day
            c.hour = newValue.Hour; c.minute = newValue.Minute; c.second = newValue.Second
            _date = Calendar.current.date(from: c) ?? Date()
            dp?.dateValue = _date
            ValueChanged?()
        }
    }
}

// ---------------------------------------------------------------- ToolStrip menus → NSMenu

class ToolStripItem {
    var _text = ""
    var Text: String { get { return _text } set { _text = newValue } }
    var Enabled = true
    var Visible = true
    var Available: Bool { get { return Visible } set { Visible = newValue } }
    var Tag: Any? = nil
    var Name = ""
    var ToolTipText = ""
    var Image: Any? = nil
    var Font: FontT? = nil
    var ForeColor: Color? = nil
    var Click: (() -> Void)? = nil
    weak var Owner: ContextMenuStrip? = nil
    init() { }
    init(_ text: String) { _text = text }
    func PerformClick() { if Enabled { OnClick(EventArgs.Empty) } }
    func OnClick(_ e: EventArgs) { Click?() }
    func Dispose() { }
}

final class ToolStripSeparator: ToolStripItem {
    override init() { super.init() }
}

// a non-clickable label row (the pixel menu draws it as a small section header)
final class ToolStripLabel: ToolStripItem {
    override init() { super.init() }
    override init(_ text: String) { super.init(text) }
}

class ToolStripMenuItem: ToolStripItem {
    var Checked = false
    var CheckOnClick = false
    var ShortcutKeyDisplayString = ""
    lazy var DropDownItems = ToolStripItemCollection()
    var DropDownOpening: (() -> Void)? = nil
    override init() { super.init() }
    override init(_ text: String) { super.init(text) }
    init(_ text: String, _ image: Any?, _ onClick: (() -> Void)?) { super.init(text); Image = image; Click = onClick }
    init(_ text: String, _ image: Any?, _ items: [ToolStripItem]) { super.init(text); Image = image; DropDownItems.AddRange(items) }
    var HasDropDownItems: Bool { return DropDownItems.Count > 0 }
    override func OnClick(_ e: EventArgs) { if CheckOnClick { Checked = !Checked }; super.OnClick(e) }
}

final class ToolStripItemCollection: Sequence {
    private(set) var items: [ToolStripItem] = []
    init() { }
    @discardableResult func Add(_ item: ToolStripItem) -> Int { items.append(item); return items.count - 1 }
    @discardableResult func Add(_ text: String) -> ToolStripItem { let it = ToolStripMenuItem(text); items.append(it); return it }
    @discardableResult func Add(_ text: String, _ image: Any?, _ onClick: (() -> Void)?) -> ToolStripItem {
        let it = ToolStripMenuItem(text, image, onClick); items.append(it); return it
    }
    func AddRange(_ its: [ToolStripItem]) { items.append(contentsOf: its) }
    func Insert(_ i: Int, _ item: ToolStripItem) { items.insert(item, at: Swift.max(0, Swift.min(items.count, i))) }
    func Remove(_ item: ToolStripItem) { if let i = items.firstIndex(where: { $0 === item }) { items.remove(at: i) } }
    func RemoveAt(_ i: Int) { if i >= 0 && i < items.count { items.remove(at: i) } }
    func Clear() { items.removeAll() }
    func Contains(_ item: ToolStripItem) -> Bool { return items.contains { $0 === item } }
    func IndexOf(_ item: ToolStripItem) -> Int { return items.firstIndex { $0 === item } ?? -1 }
    var Count: Int { return items.count }
    subscript(_ i: Int) -> ToolStripItem { return items[i] }
    func makeIterator() -> IndexingIterator<[ToolStripItem]> { return items.makeIterator() }
}

final class _MenuBridge: NSObject, NSMenuDelegate {
    var picked: ToolStripItem? = nil
    var onClose: (() -> Void)? = nil
    @objc func fire(_ sender: NSMenuItem) { picked = sender.representedObject as? ToolStripItem }
    func menuDidClose(_ menu: NSMenu) { }

    func build(_ items: ToolStripItemCollection) -> NSMenu {
        let m = NSMenu()
        m.autoenablesItems = false
        for it in items {
            if it is ToolStripSeparator { m.addItem(NSMenuItem.separator()); continue }
            if !it.Available { continue }
            let ni = NSMenuItem(title: it.Text, action: nil, keyEquivalent: "")
            ni.isEnabled = it.Enabled
            if let mi = it as? ToolStripMenuItem {
                if mi.Checked { ni.state = .on }
                if mi.DropDownItems.Count > 0 { mi.DropDownOpening?(); ni.submenu = build(mi.DropDownItems); m.addItem(ni); continue }
            }
            ni.representedObject = it
            ni.target = self
            ni.action = #selector(_MenuBridge.fire(_:))
            m.addItem(ni)
        }
        return m
    }
}

class ContextMenuStrip {
    let Items = ToolStripItemCollection()
    // events: C# `Opening += delegate(object s, CancelEventArgs e) {…}` → `Opening = { … }`
    var Opening: (() -> Void)? = nil
    var Closed: (() -> Void)? = nil
    var ItemClicked: ((ToolStripItem) -> Void)? = nil
    var ShowImageMargin = true
    var ShowCheckMargin = false
    var Renderer: Any? = nil
    var Font: FontT? = nil
    var Tag: Any? = nil
    var _visible = false
    var Visible: Bool { return _visible }
    var IsDisposed = false
    init() { }

    // shows synchronously at a global top-left screen point; Click runs after the menu has closed (main thread)
    func Show(_ p: Point) {
        if !Foundation.Thread.isMainThread { DispatchQueue.main.async { self.Show(p) }; return }
        Opening?()
        let br = _MenuBridge()
        let m = br.build(Items)
        _visible = true
        m.popUp(positioning: nil, at: _Coords.pointToCocoa(p.X, p.Y), in: nil)
        _visible = false
        Closed?()
        if let it = br.picked {
            ItemClicked?(it)
            DispatchQueue.main.async { it.PerformClick() }
        }
    }
    func Show(_ x: Int, _ y: Int) { Show(PointT(x, y)) }
    func Show(_ c: Control, _ p: Point) { Show(c.PointToScreen(p)) }
    func Close() { }
    func Dispose() { IsDisposed = true }
}

// ---------------------------------------------------------------- Application / MessageBox

enum Application {
    static func Run() { NSApp.run() }
    static func Run(_ f: Form) { f.Show(); NSApp.run() }
    static func Exit() { _Coords.onMain { NSApp.terminate(nil) } }
    static func ExitThread() { Exit() }
    static func EnableVisualStyles() { }
    static func SetCompatibleTextRenderingDefault(_ b: Bool) { }
    // pump pending events once (like WinForms DoEvents)
    static func DoEvents() {
        guard Foundation.Thread.isMainThread else { return }
        while let e = NSApp.nextEvent(matching: .any, until: Date.distantPast, inMode: .default, dequeue: true) { NSApp.sendEvent(e) }
        RunLoop.current.run(mode: .default, before: Date())
    }
    static var OpenForms: [Form] { return Form._all }
    static var StartupPath: String { return (Bundle.main.executablePath as NSString?)?.deletingLastPathComponent ?? FileManager.default.currentDirectoryPath }
    static var ExecutablePath: String { return Bundle.main.executablePath ?? CommandLine.arguments[0] }
}

enum MessageBox {
    @discardableResult static func Show(_ text: String) -> DialogResult { return Show(text, "", .OK, .None) }
    @discardableResult static func Show(_ text: String, _ caption: String) -> DialogResult { return Show(text, caption, .OK, .None) }
    @discardableResult static func Show(_ text: String, _ caption: String, _ buttons: MessageBoxButtons) -> DialogResult { return Show(text, caption, buttons, .None) }
    @discardableResult static func Show(_ text: String, _ caption: String, _ buttons: MessageBoxButtons, _ icon: MessageBoxIcon) -> DialogResult {
        if !Foundation.Thread.isMainThread { var r = DialogResult.None; DispatchQueue.main.sync { r = Show(text, caption, buttons, icon) }; return r }
        let a = NSAlert()
        a.messageText = caption.isEmpty ? text : caption
        if !caption.isEmpty { a.informativeText = text }
        a.alertStyle = (icon == .Warning || icon == .Exclamation || icon == .Error || icon == .Hand || icon == .Stop) ? .warning : .informational
        var res: [DialogResult] = []
        switch buttons {
        case .OK: a.addButton(withTitle: "OK"); res = [.OK]
        case .OKCancel: a.addButton(withTitle: "OK"); a.addButton(withTitle: "Cancel"); res = [.OK, .Cancel]
        case .YesNo: a.addButton(withTitle: "Yes"); a.addButton(withTitle: "No"); res = [.Yes, .No]
        case .YesNoCancel: a.addButton(withTitle: "Yes"); a.addButton(withTitle: "No"); a.addButton(withTitle: "Cancel"); res = [.Yes, .No, .Cancel]
        case .RetryCancel: a.addButton(withTitle: "Retry"); a.addButton(withTitle: "Cancel"); res = [.Retry, .Cancel]
        case .AbortRetryIgnore: a.addButton(withTitle: "Abort"); a.addButton(withTitle: "Retry"); a.addButton(withTitle: "Ignore"); res = [.Abort, .Retry, .Ignore]
        }
        if #available(macOS 14.0, *) { NSApp.activate() } else { NSApp.activate(ignoringOtherApps: true) }
        let r = a.runModal().rawValue - NSApplication.ModalResponse.alertFirstButtonReturn.rawValue
        return r >= 0 && r < res.count ? res[r] : .Cancel
    }
}

// ---------------------------------------------------------------- drawing interop (adapts to 01_drawing.swift)

func _formsNSColor(_ c: Color) -> NSColor {
    return NSColor(srgbRed: CGFloat(c.R) / 255.0, green: CGFloat(c.G) / 255.0, blue: CGFloat(c.B) / 255.0, alpha: CGFloat(c.A) / 255.0)
}

// ===== 03_shim_custom_a.swift =====
// 03_shim_custom_a.swift — System.Drawing bits the custom-pal renderer (53_custom.swift) needs:
// - Matrix(m11, m12, m21, m22, dx, dy) and Matrix.Clone() (Translate/Rotate/Scale already prepend like GDI+, see 01_drawing.swift)
// - Graphics.DrawImage(img, PointF[3] destParallelogram, srcRect, unit[, ImageAttributes]) — GDI+'s three-point overload
// - ImageAttributes with a full ColorMatrix: applied per pixel (un-premultiplied, clamped, re-premultiplied) like GDI+
// - Bitmap.CuReadP / CuWriteP: raw premultiplied ARGB of the device pixels (= C# LockBits Format32bppPArgb on a 1× bitmap)
import Foundation
import CoreGraphics

extension Matrix {
    /// GDI+ `new Matrix(m11, m12, m21, m22, dx, dy)`: (x, y) → (x·m11 + y·m21 + dx, x·m12 + y·m22 + dy)
    convenience init(_ m11: Double, _ m12: Double, _ m21: Double, _ m22: Double, _ dx: Double, _ dy: Double) {
        self.init(CGAffineTransform(a: CGFloat(m11), b: CGFloat(m12), c: CGFloat(m21), d: CGFloat(m22), tx: CGFloat(dx), ty: CGFloat(dy)))
    }
    func Clone() -> Matrix { return Matrix(t) }
}

extension Graphics {
    /// `g.DrawImage(img, new PointF[] { upperLeft, upperRight, lowerLeft }, srcRect, GraphicsUnit.Pixel)`
    func DrawImage(_ b: Bitmap?, _ pts: [PointF], _ src: RectangleF, _ unit: GraphicsUnit) { DrawImage(b, pts, src, unit, nil) }
    func DrawImage(_ b: Bitmap?, _ pts: [PointF], _ src: RectangleF, _ unit: GraphicsUnit, _ ia: ImageAttributes?) {
        guard let b = b, pts.count >= 3, src.Width > 0, src.Height > 0 else { return }
        let p0 = pts[0], p1 = pts[1], p2 = pts[2]
        // 把 (0,0)-(w,h) 對到平行四邊形（左上、右上、左下），再接上目前的世界座標
        let a = CGAffineTransform(a: CGFloat((p1.X - p0.X) / src.Width), b: CGFloat((p1.Y - p0.Y) / src.Width),
                                  c: CGFloat((p2.X - p0.X) / src.Height), d: CGFloat((p2.Y - p0.Y) / src.Height),
                                  tx: CGFloat(p0.X), ty: CGFloat(p0.Y))
        let old = Transform
        Transform = Matrix(a.concatenating(old.t))
        DrawImage(b, RectangleF(0, 0, src.Width, src.Height), src.X, src.Y, src.Width, src.Height, unit, ia)
        Transform = old
    }
}

extension ImageAttributes {
    /// 只有 Matrix33（透明度）不是 1 的話照舊用 setAlpha；其他的（上色、變暗）逐像素算
    var CuNeedsPixelPass: Bool {
        guard let m = matrix else { return false }
        for i in 0..<5 {
            for j in 0..<5 {
                if i == 3 && j == 3 { continue }
                let want: Double = i == j ? 1 : 0
                if m.M[i][j] != want { return true }
            }
        }
        return false
    }

    /// GDI+ ColorMatrix: out = [r g b a 1] · M（0…1、不預乘），超出 0…1 就截掉
    func CuApply(_ img: CGImage) -> CGImage? {
        guard let m = matrix else { return img }
        let w = img.width, h = img.height
        guard let c = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0, space: _gdiColorSpace,
                                bitmapInfo: CGImageAlphaInfo.premultipliedFirst.rawValue | CGBitmapInfo.byteOrder32Little.rawValue) else { return nil }
        c.setBlendMode(.copy)
        c.draw(img, in: CGRect(x: 0, y: 0, width: w, height: h))
        guard let data = c.data else { return nil }
        let p = data.assumingMemoryBound(to: UInt8.self)
        let bpr = c.bytesPerRow
        let M = m.M
        func cl(_ v: Double) -> Double { return v < 0 ? 0 : (v > 1 ? 1 : v) }
        for y in 0..<h {
            var o = y * bpr
            for _ in 0..<w {
                let a0 = Double(p[o + 3]) / 255
                var r = 0.0, g = 0.0, b = 0.0
                if a0 > 0 { b = Double(p[o]) / 255 / a0; g = Double(p[o + 1]) / 255 / a0; r = Double(p[o + 2]) / 255 / a0 }
                let nr = cl(r * M[0][0] + g * M[1][0] + b * M[2][0] + a0 * M[3][0] + M[4][0])
                let ng = cl(r * M[0][1] + g * M[1][1] + b * M[2][1] + a0 * M[3][1] + M[4][1])
                let nb = cl(r * M[0][2] + g * M[1][2] + b * M[2][2] + a0 * M[3][2] + M[4][2])
                let na = cl(r * M[0][3] + g * M[1][3] + b * M[2][3] + a0 * M[3][3] + M[4][3])
                p[o] = UInt8((nb * na * 255).rounded()); p[o + 1] = UInt8((ng * na * 255).rounded()); p[o + 2] = UInt8((nr * na * 255).rounded()); p[o + 3] = UInt8((na * 255).rounded())
                o += 4
            }
        }
        return c.makeImage()
    }
}

extension Bitmap {
    /// 裝置像素（寬 PixelWidth × 高 PixelHeight，第 0 列＝最上面），預乘的 0xAARRGGBB
    func CuReadP() -> [Int] {
        let w = ctx.width, h = ctx.height
        var out = [Int](repeating: 0, count: w * h)
        guard let d = ctx.data else { return out }
        let p = d.assumingMemoryBound(to: UInt8.self)
        let bpr = ctx.bytesPerRow
        for y in 0..<h {
            var o = y * bpr
            for x in 0..<w {
                out[y * w + x] = (Int(p[o + 3]) << 24) | (Int(p[o + 2]) << 16) | (Int(p[o + 1]) << 8) | Int(p[o])
                o += 4
            }
        }
        return out
    }
    func CuWriteP(_ px: [Int]) {
        let w = ctx.width, h = ctx.height
        guard let d = ctx.data, px.count >= w * h else { return }
        let p = d.assumingMemoryBound(to: UInt8.self)
        let bpr = ctx.bytesPerRow
        for y in 0..<h {
            var o = y * bpr
            for x in 0..<w {
                let v = px[y * w + x]
                p[o] = UInt8(v & 255); p[o + 1] = UInt8((v >> 8) & 255); p[o + 2] = UInt8((v >> 16) & 255); p[o + 3] = UInt8((v >> 24) & 255)
                o += 4
            }
        }
    }
}

// ===== 04_shim_custom_b.swift =====
// 04_shim_custom_b.swift — WinForms bits the custom-pal maker / share / .deskpal port needs (55–57).
// - Form drag-and-drop (AllowDrop, DragEnter, DragDrop, DragEventArgs, DataFormats.FileDrop, DragDropEffects):
//   FormView (02_forms.swift) forwards draggingEntered / performDragOperation to Form._dragEntered / _performDrag below.
//   Form has no room for stored properties in an extension, so the drag settings live in a side table.
// - OpenFileDialog / SaveFileDialog → NSOpenPanel / NSSavePanel (CuDialogs).
// - TextBox.PreferredHeight.
import AppKit
import UniformTypeIdentifiers

// ---------------------------------------------------------------- drag & drop

enum DataFormats {
    static let FileDrop = "FileDrop"
    static let UnicodeText = "UnicodeText"
}
enum DragDropEffects { case None, Copy, Move, Link, All }

/// e.Data：只有拖進來的檔案（WinForms 的 FileDrop＝string[] 完整路徑）
final class DragData {
    let files: [String]
    init(_ files: [String]) { self.files = files }
    func GetDataPresent(_ format: String) -> Bool { return format == DataFormats.FileDrop && files.count > 0 }
    func GetData(_ format: String) -> Any? { return format == DataFormats.FileDrop ? files : nil }
}

final class DragEventArgs: EventArgs {
    let Data: DragData
    var Effect = DragDropEffects.None
    init(_ d: DragData) { Data = d; super.init() }
}

final class _FormDragInfo {
    var allow = false
    var enter: ((DragEventArgs) -> Void)? = nil
    var drop: ((DragEventArgs) -> Void)? = nil
    var lastEffect = DragDropEffects.None
}
var _formDragTable: [ObjectIdentifier: _FormDragInfo] = [:]

extension Form {
    var _drag: _FormDragInfo {
        let k = ObjectIdentifier(self)
        if let d = _formDragTable[k] { return d }
        let d = _FormDragInfo(); _formDragTable[k] = d
        return d
    }
    var AllowDrop: Bool {
        get { return _drag.allow }
        set { _drag.allow = newValue; _applyAllowDrop() }
    }
    // C# `DragEnter += delegate(object s, DragEventArgs e) {…}` → `DragEnter = { e in … }`
    var DragEnter: ((DragEventArgs) -> Void)? {
        get { return _drag.enter }
        set { _drag.enter = newValue }
    }
    var DragDrop: ((DragEventArgs) -> Void)? {
        get { return _drag.drop }
        set { _drag.drop = newValue }
    }
    /// 視窗是 Show 的時候才建（_ensure）：顯示之後再呼叫一次，把 FormView 登記成可以放檔案
    func _applyAllowDrop() {
        guard let v = view else { return }
        if _drag.allow { v.registerForDraggedTypes([.fileURL]) } else { v.unregisterDraggedTypes() }
    }
    static func _dragFiles(_ s: NSDraggingInfo) -> [String] {
        let urls = s.draggingPasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL] ?? []
        return urls.map { $0.path }
    }
    func _dragEntered(_ s: NSDraggingInfo) -> NSDragOperation {
        if !_drag.allow { return [] }
        let e = DragEventArgs(DragData(Form._dragFiles(s)))
        _drag.enter?(e)
        _drag.lastEffect = e.Effect
        switch e.Effect {
        case .Copy, .All: return .copy
        case .Move: return .move
        case .Link: return .link
        default: return []
        }
    }
    func _performDrag(_ s: NSDraggingInfo) -> Bool {
        if !_drag.allow || _drag.lastEffect == .None { return false }
        let e = DragEventArgs(DragData(Form._dragFiles(s)))
        e.Effect = _drag.lastEffect
        // 跟 WinForms 一樣：放下的那一刻在 UI 執行緒上處理（下一輪，讓拖曳動畫先結束）
        let h = _drag.drop
        DispatchQueue.main.async { h?(e) }
        return true
    }
}

// ---------------------------------------------------------------- file dialogs

/// mac: OpenFileDialog / SaveFileDialog（Filter 的副檔名 → allowedContentTypes；InitialDirectory → directoryURL）
enum CuDialogs {
    static func Types(_ exts: [String]) -> [UTType] {
        var out: [UTType] = []
        for e in exts { if let t = UTType(filenameExtension: e) { out.append(t) } }
        return out
    }
    /// 回傳選到的完整路徑；取消回 nil
    static func Open(_ title: String, _ exts: [String], _ dir: String) -> String? {
        NSApp.activate(ignoringOtherApps: true)
        let p = NSOpenPanel()
        p.title = title; p.message = title
        p.canChooseFiles = true; p.canChooseDirectories = false; p.allowsMultipleSelection = false
        let ts = Types(exts)
        if ts.count > 0 { p.allowedContentTypes = ts }
        if !dir.isEmpty { p.directoryURL = URL(fileURLWithPath: dir, isDirectory: true) }
        p.level = .floating
        let r = p.runModal()
        Form._maybeDeactivate()
        if r != .OK { return nil }
        return p.url?.path
    }
    static func Save(_ title: String, _ fileName: String, _ exts: [String], _ dir: String) -> String? {
        NSApp.activate(ignoringOtherApps: true)
        let p = NSSavePanel()
        p.title = title; p.message = title
        p.nameFieldStringValue = fileName
        let ts = Types(exts)
        if ts.count > 0 { p.allowedContentTypes = ts }
        if !dir.isEmpty { p.directoryURL = URL(fileURLWithPath: dir, isDirectory: true) }
        p.level = .floating
        let r = p.runModal()
        Form._maybeDeactivate()
        if r != .OK { return nil }
        return p.url?.path
    }
}

// ---------------------------------------------------------------- TextBox

extension TextBox {
    /// WinForms：字型行高（BorderStyle.None 時沒有外框的空間）
    var PreferredHeight: Int {
        let f = _formsNSFont(Font)
        return Int((f.ascender - f.descender + f.leading).rounded(.up)) + 2
    }
}

// ===== 10_platform.swift =====
// Desk Pals（公仔櫃）：桌面上的像素公仔們（Spidey、小波、史迪仔、人魚漢頓…）。
// 獨立程式；一個 World 管全部：視窗掃描、公仔櫃、球、煙火、Claude／Codex 監看、pipe；0～4 隻公仔同時在桌面上跑。
// 角色＝Pal（資料：調色盤、像素圖、台詞、移動風格），新增角色＝加一個 Pal（＋需要的話加專屬動作）。
// 10_platform.swift — port of DeskPals.cs lines 1–581 (App, W, WinInfo, Plat, Client, OverlayForm, BubbleForm,
// BallForm, FxForm, FlashForm, CobwebForm, PetForm) + program entry (App.Main, called from 99_main.swift).
// mac: pipe → Unix domain socket（argv[1]），Win32 視窗 API → CGWindowList／AppKit，RegisterHotKey → Carbon。

import AppKit
import Carbon

enum App {
    static var logged = 0
    // 測試用：DESKPALS_OFFSCREEN=1 時所有視窗都不顯示，畫面改畫進虛擬螢幕（pipe 的 snap 指令存成 PNG）
    static let Offscreen = ProcessInfo.processInfo.environment["DESKPALS_OFFSCREEN"] == "1"
    // 測試用：離屏＋DESKPALS_ISOLATED=1 時不看真的視窗（不跳上你的視窗、你全螢幕也不會躲起來），截圖比較乾淨
    static let Isolated = Offscreen && ProcessInfo.processInfo.environment["DESKPALS_ISOLATED"] == "1"

    // mac: ~/Library/Logs/desk-pals.log
    static let LogPath: String = (NSHomeDirectory() as NSString).appendingPathComponent("Library/Logs/desk-pals.log")
    static let logLock = NSLock()
    static func Append(_ line: String) {
        logLock.lock(); defer { logLock.unlock() }
        guard let data = line.data(using: .utf8) else { return }
        if let fh = FileHandle(forWritingAtPath: LogPath) {
            fh.seekToEndOfFile(); fh.write(data); fh.closeFile()
        } else {
            try? FileManager.default.createDirectory(atPath: (LogPath as NSString).deletingLastPathComponent, withIntermediateDirectories: true)
            FileManager.default.createFile(atPath: LogPath, contents: data)
        }
    }
    static func Stamp(_ fmt: String) -> String {
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_US_POSIX")
        f.dateFormat = fmt
        return f.string(from: Date())
    }

    // 診斷用：不受行數上限限制
    static func LogAlways(_ s: String) {
        Append(Stamp("HH:mm:ss.SSS") + " " + s + "\n")
    }

    static func Log(_ s: String) {
        logLock.lock(); logged += 1; let n = logged; logLock.unlock()
        if n - 1 > 80 { return }
        Append(Stamp("yyyy-MM-dd'T'HH:mm:ss") + " " + s + "\n")
    }

    static func Run(_ pipeName: String, _ pet: String) { Run(pipeName, pet, "") }
    // lineup：classic（經典一櫃）／teletubbies（天線寶寶一櫃）；空白＝照上次的
    // mac: pipeName = Unix socket 路徑；單一執行個體用 socket 旁邊的 .lock 檔 flock（取代 Mutex）
    static var lockFd: Int32 = -1
    static func Run(_ pipeName: String, _ pet: String, _ lineup: String) {
        let lockPath = pipeName + ".lock"
        try? FileManager.default.createDirectory(atPath: (lockPath as NSString).deletingLastPathComponent, withIntermediateDirectories: true)
        let fd = open(lockPath, O_CREAT | O_RDWR, 0o644)
        if fd < 0 || flock(fd, LOCK_EX | LOCK_NB) != 0 { Log("already running"); if fd >= 0 { close(fd) }; return }
        lockFd = fd   // 一直開著到程式結束
        let app = NSApplication.shared
        app.setActivationPolicy(.accessory)
        NSSetUncaughtExceptionHandler { ex in App.LogAlways("ui: " + ex.name.rawValue + " " + (ex.reason ?? "")) }
        let w = World(pipeName, pet, lineup)
        w.Start()
        app.run()
    }
// <fan>

    // 開發用：把每個角色的各種姿勢畫成一張圖（不會開任何視窗）
    static func Preview(_ path: String, _ night: Bool) {
        Pet.PreviewSheet(path, night)
    }
    // </fan>
    static func PreviewShelf(_ path: String, _ night: Bool) {
        Pet.PreviewShelf(path, night)
    }
    // <fan>
    // 開發用：天線寶寶一櫃的各種姿勢
    static func PreviewTubbies(_ path: String, _ night: Bool) {
        Pet.PreviewTubbySheet(path, night)
    }
    // </fan>

    // mac: 程式進入點（99_main.swift 呼叫）
    // DeskPals [socket] [pet] [lineup]
    // DeskPals --preview out.png [night] | --preview-shelf out.png [night] | --preview-tubbies out.png [night]
    static func Main() {
        signal(SIGPIPE, SIG_IGN)
        let a = CommandLine.arguments
        if a.count >= 3 && (a[1] == "--preview" || a[1] == "--preview-shelf" || a[1] == "--preview-tubbies") {   //@fan
        // <public> if a.count >= 3 && a[1] == "--preview-shelf" {
            let night = a.count >= 4 && (a[3] == "night" || a[3] == "1" || a[3].lowercased() == "true")
            // <fan>
            if a[1] == "--preview" { Preview(a[2], night) }
            else if a[1] == "--preview-shelf" { PreviewShelf(a[2], night) }
            else { PreviewTubbies(a[2], night) }
            // </fan>
            // <public> PreviewShelf(a[2], night)
            exit(0)
        }
        let def = (NSHomeDirectory() as NSString).appendingPathComponent("Library/Application Support/SpideyDesktop/spidey.sock")
        let sock = a.count >= 2 && !a[1].isEmpty ? a[1] : def
        let pet = a.count >= 3 ? a[2] : ""
        let lineup = a.count >= 4 ? a[3] : ""
        Run(sock, pet, lineup)
    }
}

// Win32 視窗 API 的 mac 版：IntPtr 視窗代碼＝CGWindowID（kCGWindowNumber），座標＝全域左上角原點
enum W {
    typealias EnumProc = (IntPtr, IntPtr) -> Bool
    struct RECT { var L = 0, T = 0, R = 0, B = 0; init() { }; init(_ l: Int, _ t: Int, _ r: Int, _ b: Int) { L = l; T = t; R = r; B = b } }

    // ---- 視窗快照（CGWindowListCopyWindowInfo；EnumWindows 時更新，單一視窗查詢時 0.25 秒內直接用）
    final class Snap { var H: IntPtr = 0; var Pid = 0; var Owner = ""; var Name = ""; var L = 0, T = 0, R = 0, B = 0; var Layer = 0; var Alpha = 1.0; var OnScreen = true; var At = 0.0 }
    static var snaps: [IntPtr: Snap] = [:]
    static var order: [Snap] = []          // 最近一次 EnumWindows：由前到後
    static var orderAt = -1.0
    static let snapLock = NSLock()
    static func Now() -> Double { return ProcessInfo.processInfo.systemUptime }
    static func MakeSnap(_ info: [String: Any], _ at: Double) -> Snap? {
        let s = Snap()
        s.H = (info[kCGWindowNumber as String] as? NSNumber)?.intValue ?? 0
        if s.H == 0 { return nil }
        s.Pid = (info[kCGWindowOwnerPID as String] as? NSNumber)?.intValue ?? 0
        s.Owner = (info[kCGWindowOwnerName as String] as? String) ?? ""
        s.Name = (info[kCGWindowName as String] as? String) ?? ""
        s.Layer = (info[kCGWindowLayer as String] as? NSNumber)?.intValue ?? 0
        s.Alpha = (info[kCGWindowAlpha as String] as? NSNumber)?.doubleValue ?? 1
        s.OnScreen = (info[kCGWindowIsOnscreen as String] as? NSNumber)?.boolValue ?? false
        if let bd = info[kCGWindowBounds as String] as? NSDictionary, let r = CGRect(dictionaryRepresentation: bd as CFDictionary) {
            s.L = Int(r.minX.rounded()); s.T = Int(r.minY.rounded()); s.R = Int(r.maxX.rounded()); s.B = Int(r.maxY.rounded())
        }
        s.At = at
        return s
    }
    static func Info(_ h: IntPtr) -> Snap? {
        if h == 0 { return nil }
        let now = Now()
        snapLock.lock()
        if let s = snaps[h], now - s.At < 0.25 { snapLock.unlock(); return s.OnScreen ? s : nil }
        snapLock.unlock()
        guard let arr = CGWindowListCopyWindowInfo([.optionIncludingWindow], CGWindowID(UInt32(truncatingIfNeeded: h))) as? [[String: Any]],
              let info = arr.first, let s = MakeSnap(info, now) else {
            snapLock.lock(); snaps.removeValue(forKey: h); snapLock.unlock()
            return nil
        }
        snapLock.lock(); snaps[h] = s; snapLock.unlock()
        return s.OnScreen ? s : nil
    }
    static func Refresh() -> [Snap] {
        let now = Now()
        var out: [Snap] = []
        let myPid = Int(ProcessInfo.processInfo.processIdentifier)
        if let list = CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] {
            for info in list {
                guard let s = MakeSnap(info, now) else { continue }
                s.OnScreen = true
                if s.Pid == myPid || s.Layer != 0 || s.Alpha <= 0.01 { continue }
                out.append(s)
            }
        }
        snapLock.lock()
        for s in out { snaps[s.H] = s }
        if snaps.count > 2000 { snaps = snaps.filter { now - $0.value.At < 5 } }
        order = out; orderAt = now
        snapLock.unlock()
        return out
    }

    // 由前到後列舉別的 App 的一般視窗（layer 0、略過自己的 PID）
    @discardableResult static func EnumWindows(_ cb: EnumProc, _ l: IntPtr) -> Bool {
        for s in Refresh() { if !cb(s.H, l) { break } }
        return true
    }
    static func IsWindowVisible(_ h: IntPtr) -> Bool {
        if let f = Form._FromHandle(h) { return f.Visible }
        return Info(h) != nil
    }
    // mac: 縮到 Dock 的視窗不在畫面上 → IsWindowVisible 已經是 false
    static func IsIconic(_ h: IntPtr) -> Bool { return false }
    // 視窗樣式：自己的視窗照實際狀態回報 TOOLWINDOW/NOACTIVATE/TOPMOST/LAYERED/TRANSPARENT；別人的視窗回 0
    @discardableResult static func GetWindowLong(_ h: IntPtr, _ i: Int) -> Int {
        guard let f = Form._FromHandle(h) else { return 0 }
        if i == -20 {
            var ex = 0
            if !f._isDialog { ex |= 0x80 | 0x08000000 | 0x8 }
            if let p = f.panel, p.ignoresMouseEvents { ex |= 0x80000 | 0x20 }
            return ex
        }
        if i == -16 { return f._isDialog ? 0x00C00000 : 0 }
        return 0
    }
    // 只支援 GWL_EXSTYLE 的 WS_EX_TRANSPARENT（點得穿）→ ignoresMouseEvents
    @discardableResult static func SetWindowLong(_ h: IntPtr, _ i: Int, _ v: Int) -> Int {
        let old = GetWindowLong(h, i)
        if i == -20, let f = Form._FromHandle(h), let p = f.panel { p.ignoresMouseEvents = (v & 0x20) != 0 }
        return old
    }
    // mac: 自己的對話框 → 拉到前景、變成 key；別的 App 的視窗 → 啟動那個 App；看不見的小視窗（選單宿主）→ 不用搶焦點
    @discardableResult static func SetForegroundWindow(_ h: IntPtr) -> Bool {
        if let f = Form._FromHandle(h) {
            if !f._isDialog { return true }   // mac: NSMenu 不需要宿主視窗在前景
            f.Activate()
            return true
        }
        guard let s = Info(h), let app = NSRunningApplication(processIdentifier: pid_t(s.Pid)) else { return false }
        if #available(macOS 14.0, *) { NSApp.yieldActivation(to: app); return app.activate(options: []) }
        return app.activate(options: [])
    }
    @discardableResult static func BringWindowToTop(_ h: IntPtr) -> Bool {
        if let f = Form._FromHandle(h) { f.panel?.orderFrontRegardless(); return true }
        return false
    }
    @discardableResult static func AttachThreadInput(_ idAttach: Int, _ idAttachTo: Int, _ attach: Bool) -> Bool { return false }
    // mac: 沒有視窗訊息佇列，WM_NULL 之類不用送
    @discardableResult static func PostMessage(_ h: IntPtr, _ msg: Int, _ w: IntPtr, _ l: IntPtr) -> Bool { return true }
    static func GetCurrentThreadId() -> Int { return Int(pthread_mach_thread_np(pthread_self())) }

    // 我們的視窗都是「不搶焦點」的，選單、輸入框要先把自己拉到前景才會正常顯示／能打字
    @discardableResult static func ForceForeground(_ h: IntPtr) -> Bool {
        var ok = false
        let fg = GetForegroundWindow()
        var pid = 0
        let fgThread = fg == 0 ? 0 : GetWindowThreadProcessId(fg, &pid), me = GetCurrentThreadId()
        let att = fgThread != 0 && fgThread != me && AttachThreadInput(me, fgThread, true)
        ok = SetForegroundWindow(h)
        BringWindowToTop(h)
        if att { AttachThreadInput(me, fgThread, false) }
        let after = GetForegroundWindow()
        App.LogAlways("menu: ForceForeground set=" + (ok ? "True" : "False") + " attached=" + (att ? "True" : "False") + " fgAfter=" + (after == h ? "helper" : String(after, radix: 16, uppercase: true)))
        return ok
    }

    // ---- 原生選單（TrackPopupMenuEx）→ NSMenu.popUp（同步，回傳選到的 id，沒選＝0）
    final class MenuTarget: NSObject {
        var cmd = 0
        @objc func pick(_ sender: NSMenuItem) { cmd = sender.tag }
    }
    static var menus: [IntPtr: NSMenu] = [:]
    static var nextMenu: IntPtr = 0x4D00
    static let menuTarget = MenuTarget()
    static func CreatePopupMenu() -> IntPtr {
        nextMenu += 1
        let m = NSMenu()
        m.autoenablesItems = false
        menus[nextMenu] = m
        return nextMenu
    }
    // flags：MF_GRAYED 0x1、MF_CHECKED 0x8、MF_POPUP 0x10（id＝子選單）、MF_SEPARATOR 0x800
    @discardableResult static func AppendMenu(_ hMenu: IntPtr, _ flags: Int, _ id: IntPtr, _ text: String?) -> Bool {
        guard let m = menus[hMenu] else { return false }
        if flags & 0x0800 != 0 { m.addItem(NSMenuItem.separator()); return true }
        let t = (text ?? "").replacingOccurrences(of: "&&", with: "\u{1}").replacingOccurrences(of: "&", with: "").replacingOccurrences(of: "\u{1}", with: "&")
        let it = NSMenuItem(title: t, action: nil, keyEquivalent: "")
        it.isEnabled = flags & 0x0001 == 0 && flags & 0x0002 == 0
        if flags & 0x0008 != 0 { it.state = .on }
        if flags & 0x0010 != 0 {
            it.submenu = menus[id]
        } else {
            it.tag = id
            it.target = menuTarget
            it.action = #selector(MenuTarget.pick(_:))
        }
        m.addItem(it)
        return true
    }
    // x, y：全域左上角座標；TPM_RIGHTALIGN 0x8／TPM_BOTTOMALIGN 0x20 照 Windows 對齊；回傳選到的 id
    static func TrackPopupMenuEx(_ hMenu: IntPtr, _ flags: Int, _ x: Int, _ y: Int, _ hwnd: IntPtr, _ tpm: IntPtr) -> Int {
        guard let m = menus[hMenu] else { return 0 }
        if !Foundation.Thread.isMainThread { var r = 0; DispatchQueue.main.sync { r = TrackPopupMenuEx(hMenu, flags, x, y, hwnd, tpm) }; return r }
        menuTarget.cmd = 0
        var loc = _Coords.pointToCocoa(x, y)
        let sz = m.size
        if flags & 0x0008 != 0 { loc.x -= sz.width }
        if flags & 0x0020 != 0 { loc.y += sz.height }
        m.popUp(positioning: nil, at: loc, in: nil)
        let c = menuTarget.cmd
        menuTarget.cmd = 0
        return c
    }
    @discardableResult static func DestroyMenu(_ hMenu: IntPtr) -> Bool {
        guard let m = menus.removeValue(forKey: hMenu) else { return false }
        for it in m.items { if let sm = it.submenu, let k = menus.first(where: { $0.value === sm })?.key { _ = DestroyMenu(k) } }
        return true
    }

    static func GetWindowTextLength(_ h: IntPtr) -> Int { return GetText(h).count }
    // mac: 標題（kCGWindowName）沒有「螢幕錄影」權限時是空的 → 用 App 名字代替（不然候選視窗全都沒標題）
    static func GetText(_ h: IntPtr) -> String {
        if let f = Form._FromHandle(h) { return f.Text }
        guard let s = Info(h) else { return "" }
        return s.Name.isEmpty ? s.Owner : s.Name
    }
    @discardableResult static func GetWindowRect(_ h: IntPtr, _ r: inout RECT) -> Bool {
        if let f = Form._FromHandle(h) { r = RECT(f.Left, f.Top, f.Left + f.Width, f.Top + f.Height); return true }
        guard let s = Info(h) else { return false }
        r = RECT(s.L, s.T, s.R, s.B)
        return true
    }
    // 前景視窗：自己是前景 App → 自己的 key window；否則前景 App 最前面的 layer 0 視窗
    static func GetForegroundWindow() -> IntPtr {
        if NSApp != nil && NSApp.isActive, let k = NSApp.keyWindow { return k.windowNumber }
        guard let front = NSWorkspace.shared.frontmostApplication else { return 0 }
        let pid = Int(front.processIdentifier)
        if pid == Int(ProcessInfo.processInfo.processIdentifier) { return NSApp?.keyWindow?.windowNumber ?? 0 }
        snapLock.lock()
        let fresh = Now() - orderAt < 0.5
        let cur = order
        snapLock.unlock()
        for s in (fresh ? cur : Refresh()) where s.Pid == pid { return s.H }
        return 0
    }
    // mac: 沒有視窗類別 → App 名字（Finder 的桌面不在清單裡）
    @discardableResult static func GetClassName(_ h: IntPtr, _ sb: StringBuilder, _ n: Int) -> Int {
        var s = ""
        if Form._FromHandle(h) != nil { s = "WindowsForms10.Window" } else if let i = Info(h) { s = i.Owner }
        if s.count > n - 1 { s = String(s.prefix(max(0, n - 1))) }
        sb.Clear(); sb.Append(s)
        return s.count
    }
    // 回傳值：「執行緒 id」（mac：非 0 的假值），pid：擁有者 PID
    @discardableResult static func GetWindowThreadProcessId(_ h: IntPtr, _ pid: inout Int) -> Int {
        if Form._FromHandle(h) != nil { pid = Int(ProcessInfo.processInfo.processIdentifier); return GetCurrentThreadId() }
        guard let s = Info(h) else { pid = 0; return 0 }
        pid = s.Pid
        return s.Pid + 1
    }
    @discardableResult static func GetWindowText(_ h: IntPtr, _ sb: StringBuilder, _ n: Int) -> Int {
        var s = GetText(h)
        if s.count > n - 1 { s = String(s.prefix(max(0, n - 1))) }
        sb.Clear(); sb.Append(s)
        return s.count
    }

    // ---- 快速鍵（RegisterHotKey → Carbon RegisterEventHotKey）
    // mods：MOD_ALT 1 → ⌥、MOD_CONTROL 2 → ⌃、MOD_SHIFT 4 → ⇧、MOD_WIN 8 → ⌘；vk：A–Z／0–9
    // 按下時：有設 W.OnHotKey 就呼叫它(id)；沒有就把 WM_HOTKEY（0x0312，WParam＝id）送到註冊時那個 Form 的 WndProc。
    static var OnHotKey: ((Int) -> Void)? = nil
    static var hotKeyForms: [Int: Form.WeakForm] = [:]
    static var hotKeyRefs: [Int: EventHotKeyRef] = [:]
    static var hotKeyHandler: EventHandlerRef? = nil
    static let HotKeySig: OSType = 0x4450_4B57   // 'DPKW'
    static func VkToMac(_ vk: Int) -> Int {
        let letters: [Int] = [kVK_ANSI_A, kVK_ANSI_B, kVK_ANSI_C, kVK_ANSI_D, kVK_ANSI_E, kVK_ANSI_F, kVK_ANSI_G, kVK_ANSI_H, kVK_ANSI_I,
                              kVK_ANSI_J, kVK_ANSI_K, kVK_ANSI_L, kVK_ANSI_M, kVK_ANSI_N, kVK_ANSI_O, kVK_ANSI_P, kVK_ANSI_Q, kVK_ANSI_R,
                              kVK_ANSI_S, kVK_ANSI_T, kVK_ANSI_U, kVK_ANSI_V, kVK_ANSI_W, kVK_ANSI_X, kVK_ANSI_Y, kVK_ANSI_Z]
        let digits: [Int] = [kVK_ANSI_0, kVK_ANSI_1, kVK_ANSI_2, kVK_ANSI_3, kVK_ANSI_4, kVK_ANSI_5, kVK_ANSI_6, kVK_ANSI_7, kVK_ANSI_8, kVK_ANSI_9]
        if vk >= 0x41 && vk <= 0x5A { return letters[vk - 0x41] }
        if vk >= 0x30 && vk <= 0x39 { return digits[vk - 0x30] }
        if vk == 0x20 { return kVK_Space }
        return -1
    }
    static func HotKeyFired(_ id: Int) {
        if let cb = OnHotKey { cb(id); return }
        guard let f = hotKeyForms[id]?.f else { return }
        var m = Message(f.panel?.windowNumber ?? 0, 0x0312, id, 0)
        f.WndProc(&m)
    }
    @discardableResult static func RegisterHotKey(_ h: IntPtr, _ id: Int, _ mods: Int, _ vk: Int) -> Bool {
        let key = VkToMac(vk)
        if key < 0 { return false }
        if hotKeyHandler == nil {
            var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
            let st = InstallEventHandler(GetApplicationEventTarget(), { (_, ev, _) -> OSStatus in
                var hk = EventHotKeyID()
                guard let e = ev else { return OSStatus(eventNotHandledErr) }
                let r = GetEventParameter(e, EventParamName(kEventParamDirectObject), EventParamType(typeEventHotKeyID), nil,
                                          MemoryLayout<EventHotKeyID>.size, nil, &hk)
                if r != OSStatus(noErr) || hk.signature != W.HotKeySig { return OSStatus(eventNotHandledErr) }
                let id = Int(hk.id)
                DispatchQueue.main.async { W.HotKeyFired(id) }
                return OSStatus(noErr)
            }, 1, &spec, nil, &hotKeyHandler)
            if st != OSStatus(noErr) { App.Log("hotkey handler install failed " + String(st)); return false }
        }
        var cm = 0
        if mods & 1 != 0 { cm |= optionKey }
        if mods & 2 != 0 { cm |= controlKey }
        if mods & 4 != 0 { cm |= shiftKey }
        if mods & 8 != 0 { cm |= cmdKey }
        if let old = hotKeyRefs.removeValue(forKey: id) { UnregisterEventHotKey(old) }
        var ref: EventHotKeyRef? = nil
        let st = RegisterEventHotKey(UInt32(key), UInt32(cm), EventHotKeyID(signature: HotKeySig, id: UInt32(id)), GetApplicationEventTarget(), OptionBits(0), &ref)
        if st != OSStatus(noErr) || ref == nil { return false }
        hotKeyRefs[id] = ref!
        if let f = Form._FromHandle(h) { hotKeyForms[id] = Form.WeakForm(f) }
        return true
    }
    @discardableResult static func UnregisterHotKey(_ h: IntPtr, _ id: Int) -> Bool {
        guard let r = hotKeyRefs.removeValue(forKey: id) else { return false }
        UnregisterEventHotKey(r); hotKeyForms.removeValue(forKey: id)
        return true
    }

    // 自己的視窗：SWP_NOMOVE/NOSIZE 以外就移動／改大小；after＝TOPMOST → 拉到最上面
    @discardableResult static func SetWindowPos(_ h: IntPtr, _ after: IntPtr, _ x: Int, _ y: Int, _ cx: Int, _ cy: Int, _ f: Int) -> Bool {
        guard let fm = Form._FromHandle(h) else { return false }
        let nomove = f & Int(NOMOVE) != 0, nosize = f & Int(NOSIZE) != 0
        if !nomove || !nosize { fm.SetBounds(nomove ? fm.Left : x, nomove ? fm.Top : y, nosize ? fm.Width : cx, nosize ? fm.Height : cy) }
        if after == TOPMOST && f & 0x0004 == 0 { fm.panel?.orderFrontRegardless() }
        return true
    }
    // mac: DWM 沒有；回傳非 0（失敗）→ 呼叫端改用 GetWindowRect／當作沒被隱藏
    static func DwmGetWindowAttribute(_ h: IntPtr, _ a: Int, _ r: inout RECT, _ n: Int) -> Int {
        if a == 9 && GetWindowRect(h, &r) { return 0 }
        return 1
    }
    static func DwmGetWindowAttribute(_ h: IntPtr, _ a: Int, _ v: inout Int, _ n: Int) -> Int { v = 0; return 1 }

    // 系統閒置秒數（整台電腦最後一次鍵盤／滑鼠）
    static func IdleSeconds() -> Double {
        if App.Isolated { return World.TestIdle }   // 測試：不看真的鍵盤滑鼠（act idle <秒>）   //@fan
        // <public> if App.Isolated { return 0 }
        let anyInput = CGEventType(rawValue: ~0)!
        return CGEventSource.secondsSinceLastEventType(.combinedSessionState, eventType: anyInput)
    }
    struct POINT { var X = 0, Y = 0; init() { }; init(_ x: Int, _ y: Int) { X = x; Y = y } }
    struct SIZE { var CX = 0, CY = 0; init() { }; init(_ cx: Int, _ cy: Int) { CX = cx; CY = cy } }

    // 一次完成「移動＋改大小＋換畫面」，不會有拉伸的中間畫面
    // mac: 視窗內容換成這張圖（layer.contents，Retina 用 Bitmap 的倍率），移動＋改大小在同一個 CATransaction
    static func Present(_ f: Form, _ bmp: Bitmap, _ x: Int, _ y: Int) {
        if App.Offscreen {
            if let o = f as? OverlayForm { if o.VBmp != nil { o.VBmp.Dispose() }; o.VBmp = _formsCloneBitmap(bmp); o.VPos = Point(x, y) }
            return
        }
        if !Foundation.Thread.isMainThread { DispatchQueue.main.sync { Present(f, bmp, x, y) }; return }
        let img = _formsCGImage(bmp)
        if img == nil { App.Log("ULW failed size=" + String(bmp.Width) + "x" + String(bmp.Height)) }
        f._present(img, _formsBitmapScale(bmp), x, y, bmp.Width, bmp.Height)
    }
    static let TOPMOST: IntPtr = -1
    static let NOSIZE = 1, NOMOVE = 2, NOACTIVATE = 0x10

    @discardableResult static func Rect(_ h: IntPtr, _ r: inout RECT) -> Bool {
        if DwmGetWindowAttribute(h, 9, &r, 16) == 0 { return true } // DWMWA_EXTENDED_FRAME_BOUNDS
        return GetWindowRect(h, &r)
    }
    static var SuspendZ = false    // 原生選單開著時不要把我們的視窗拉到最上面（會蓋住選單）
    static func KeepOnTop(_ f: Form?) {
        if SuspendZ { return }
        if let f = f, f.IsHandleCreated && f.Visible { f.panel?.orderFrontRegardless() }
    }
    // 有沒有在顯示（離屏測試模式看虛擬旗標）
    static func Shown(_ f: Form?) -> Bool {
        guard let f = f else { return false }
        let o = f as? OverlayForm
        return App.Offscreen && o != nil ? o!.VVisible : f.Visible
    }
}

class WinInfo { var H: IntPtr = 0; var L = 0, T = 0, R = 0, B = 0, Z = 0 }
class Plat { var H: IntPtr = 0; var Top = 0, Left = 0, Right = 0, WinLeft = 0 }
// mac: NamedPipeServerStream → 已連線的 Unix socket（fd）
class Client { var S: Int32 = -1; var Fd: Int32 { get { return S } set { S = newValue } } }

// 透明、不搶焦點、永遠在最上層的小視窗共同設定
class OverlayForm: Form {
    static let KEY = Color.FromArgb(255, 0, 255)
    var KEY: Color { return OverlayForm.KEY }   // mac: 子類別裡可以直接寫 KEY
    let clickThrough: Bool, perPixel: Bool
    init(_ clickThrough: Bool) {
        self.clickThrough = clickThrough
        self.perPixel = false
        super.init()
        Setup()
    }
    init(_ clickThrough: Bool, _ perPixel: Bool) {
        self.clickThrough = clickThrough
        self.perPixel = perPixel
        super.init()
        Setup()
    }
    func Setup() {
        FormBorderStyle = FormBorderStyleT.None
        ShowInTaskbar = false
        TopMost = true
        StartPosition = FormStartPosition.Manual
        if !perPixel { BackColor = OverlayForm.KEY; TransparencyKey = OverlayForm.KEY }
        SetStyle([ControlStyles.OptimizedDoubleBuffer, ControlStyles.AllPaintingInWmPaint, ControlStyles.UserPaint], true)
    }
    override var ShowWithoutActivation: Bool { return true }
    // 現在要不要點得穿（泡泡有通知可以點時會關掉）；視窗重建時也照這個
    var ClickThroughNow: Bool { return true }
    // mac: 取代 CreateParams 的 WS_EX_TRANSPARENT → ignoresMouseEvents（點得到的視窗：透明像素本來就點得穿）
    override var _wantsClickThrough: Bool { return clickThrough && ClickThroughNow }

    // ---- 離屏測試模式：永遠不真的顯示，只記住「應該要顯示」 ----
    var VVisible = false
    var VBmp: Bitmap! = nil
    var VPos = Point(0, 0)
    override func SetVisibleCore(_ value: Bool) {
        if App.Offscreen { VVisible = value; super.SetVisibleCore(false); return }
        super.SetVisibleCore(value)
    }
    // 把自己（非逐像素的那種）畫到虛擬螢幕上
    func PaintTo(_ g: Graphics) {
        if Width <= 0 || Height <= 0 { return }
        // mac: KEY 色畫上去就是透明，不用 MakeTransparent
        let b = Bitmap(Width, Height)
        do { let gg = Graphics.FromImage(b); OnPaint(PaintEventArgs(gg, Rectangle(0, 0, Width, Height))) }
        if Opacity < 0.999 {
            let cm = ColorMatrix(); cm.Matrix33 = Opacity
            do { let ia = ImageAttributes(); ia.SetColorMatrix(cm); g.DrawImage(b, Rectangle(Left, Top, Width, Height), 0, 0, Width, Height, GraphicsUnit.Pixel, ia) }
        }
        else { g.DrawImageUnscaled(b, Left, Top) }
    }
}

// 對話泡泡。theme：0 白天、1 黑化（Spidey）、2 夕陽（小波）、3 夜空（史迪仔）、4 燭光（人魚漢頓）
class BubbleForm: OverlayForm {
    lazy var font = Font("Microsoft JhengHei UI", 10, FontStyle.Bold)
    lazy var hintFont = Font("Microsoft JhengHei UI", 9, FontStyle.Bold)
    var text = "", hint: String? = nil
    var alert = false
    var theme = 0, hintH = 0
    var accent = Color.FromArgb(0x2A, 0x2F, 0x45)
    var owner: Pet! = nil
    var clickable = false
    init(_ accent: Color) { super.init(true); self.accent = accent }

    func Measure(_ s: String, _ a: Bool, _ th: Int, _ h: String?) -> Size {
        if s != text || a != alert || th != theme || h != hint { text = s; alert = a; theme = th; hint = h; Invalidate() }
        let ts = TextRenderer.MeasureText(s, font, Size(4000, 400), TextFormatFlags.NoPadding)
        hintH = 0
        var wd = ts.Width
        if !string.IsNullOrEmpty(h) {
            let hs = TextRenderer.MeasureText(h!, hintFont, Size(4000, 400), TextFormatFlags.NoPadding)
            hintH = hs.Height + 2; wd = Math.Max(wd, hs.Width + hs.Height + 2)
        }
        return Size(wd + 22, ts.Height + hintH + 12 + 7)
    }

    // 有通知可以點的時候，泡泡不再點得穿（點了＝打開連結）
    override var ClickThroughNow: Bool { return !clickable }
    func SetClickable(_ on: Bool, _ p: Pet!) {
        owner = p
        clickable = on
        Cursor = on ? Cursors.Hand : Cursors.Default
        if !IsHandleCreated { return }          // 還沒建立：建立時 CreateParams 會照 clickable 設
        let ex = W.GetWindowLong(Handle, -20)
        let want = on ? (ex & ~0x20) : (ex | 0x20)
        if want != ex {
            W.SetWindowLong(Handle, -20, want)
            W.SetWindowPos(Handle, 0, 0, 0, 0, 0, W.NOSIZE | W.NOMOVE | W.NOACTIVATE | 0x0004 | 0x0020) // NOZORDER | FRAMECHANGED
        }
        if on { W.KeepOnTop(self) }
    }
    override func OnMouseDown(_ e: MouseEventArgs) {
        super.OnMouseDown(e)
        if clickable && owner != nil && e.Button == MouseButtons.Left { owner.Clicked() }
    }

    static func C(_ rgb: Int) -> Color { return Color.FromArgb((rgb >> 16) & 255, (rgb >> 8) & 255, rgb & 255) }

    override func OnPaint(_ e: PaintEventArgs) {
        let C = BubbleForm.C
        let g = e.Graphics
        g.Clear(KEY)
        let w = ClientSize.Width, h = ClientSize.Height - 7
        var line: Color, fg: Color, bg: Color
        switch theme {
        case 1: line = C(0x7B6BC4); fg = C(0xEEEBF8); bg = C(0x16171F)
        case 2: line = C(0xE8935A); fg = C(0xFFEBD9); bg = C(0x3B2335)
        case 3: line = C(0x6FA8E8); fg = C(0xE4F0FF); bg = C(0x14203A)
        case 4: line = C(0xD9A050); fg = C(0xFFF1D6); bg = C(0x2E2418)
        default: line = accent; fg = C(0x2A2F45); bg = Color.White
        }
        if alert { line = C(0xC95454); fg = theme == 0 ? C(0xA83232) : C(0xFF8A8A) }
        do {
            let lb = SolidBrush(line)
            let fill = SolidBrush(bg)
            // 像素風方框（切角）＋往下的小尾巴
            g.FillRectangle(lb, 2, 0, w - 4, h)
            g.FillRectangle(lb, 0, 2, w, h - 4)
            g.FillRectangle(lb, 1, 1, w - 2, h - 2)
            g.FillRectangle(fill, 3, 2, w - 6, h - 4)
            g.FillRectangle(fill, 2, 3, w - 4, h - 6)
            let cx = w / 2
            for i in 0..<7 { g.FillRectangle(lb, cx - 7 + i, h - 2 + i, 14 - 2 * i, 1) }
            for i in 0..<5 { g.FillRectangle(fill, cx - 5 + i, h - 2 + i, 10 - 2 * i, 1) }
        }
        if text.IndexOf("\n") >= 0 {
            TextRenderer.DrawText(g, text, font, Rectangle(0, 6, w, h - hintH - 6), fg, [TextFormatFlags.HorizontalCenter, TextFormatFlags.NoPadding])
        } else {
            TextRenderer.DrawText(g, text, font, Rectangle(0, 0, w, h - hintH), fg,
                [TextFormatFlags.HorizontalCenter, TextFormatFlags.VerticalCenter, TextFormatFlags.NoPadding])
        }
        if hintH > 0 {
            // 小小的「↗」連結圖示（自己畫，不靠 emoji 字型）＋提示字
            let hint = self.hint ?? ""
            let hc = theme == 0 ? Color.FromArgb(0x3D, 0x7B, 0xD9) : Color.FromArgb(0x9F, 0xC8, 0xFF)
            let hs = TextRenderer.MeasureText(hint, hintFont, Size(4000, 400), TextFormatFlags.NoPadding)
            let ic = Math.Max(7, hs.Height - 4), tw = ic + 4 + hs.Width, x0 = (w - tw) / 2, y0 = h - hintH - 5 + (hintH - ic) / 2
            do {
                let p = Pen(hc, Math.Max(1.4, Double(ic) / 6.0))
                g.DrawRectangle(p, x0, y0 + ic / 3, ic * 2 / 3, ic * 2 / 3)
                g.DrawLine(p, x0 + ic / 3, y0 + ic * 2 / 3, x0 + ic, y0)
                g.DrawLine(p, x0 + ic / 2, y0, x0 + ic, y0)
                g.DrawLine(p, x0 + ic, y0, x0 + ic, y0 + ic / 2)
            }
            TextRenderer.DrawText(g, hint, hintFont, Point(x0 + ic + 4, h - hintH - 5 + (hintH - hs.Height) / 2), hc, TextFormatFlags.NoPadding)
        }
    }
}

// 球（點得到：點一下就把球丟出去）。kind：tennis／baseball
class BallForm: OverlayForm {
    var Kicked: (() -> Void)? = nil
    let ps: Int
    var kind = "tennis"
    static let TENNIS: [String] = ["..kkkk..", ".kTTTTk.", "kTTWTTTk", "kTWTTTTk", "kTTTTWTk", "kTTTWTTk", ".kTTTTk.", "..kkkk.."]
    static let BASEBALL: [String] = ["..gggg..", ".gWWWWg.", "gRWWWWRg", "gWRWWRWg", "gWRWWRWg", "gRWWWWRg", ".gWWWWg.", "..gggg.."]
    static let TUBBYBALL: [String] = ["..kkkk..", ".kOOYOk.", "kOYOOOOk", "kOOOOOok", "kOOOOOok", "kOOOOook", ".kooook.", "..kkkk.."]   // 天線寶寶的大橘球   //@fan
    let bk = SolidBrush(Color.FromArgb(0x2A, 0x2F, 0x45)), bt = SolidBrush(Color.FromArgb(0xD9, 0xE8, 0x4A)), bw = SolidBrush(Color.White),
        bg = SolidBrush(Color.FromArgb(0x8A, 0x90, 0xA0)), brd = SolidBrush(Color.FromArgb(0xE0, 0x3A, 0x3A)),
        bo = SolidBrush(Color.FromArgb(0xF2, 0x85, 0x2A)), bod = SolidBrush(Color.FromArgb(0xC2, 0x5E, 0x14)), byl = SolidBrush(Color.FromArgb(0xFF, 0xD8, 0x4A))
    init(_ ps: Int) { self.ps = ps; super.init(false); Size = Size(8 * ps, 8 * ps) }
    var Kind: String { get { return kind } set { if kind != newValue { kind = newValue; Invalidate() } } }
    static func Art(_ kind: String) -> [String] { return kind == "baseball" ? BASEBALL : (kind == "tubby" ? TUBBYBALL : TENNIS) }   //@fan
    // <public> static func Art(_ kind: String) -> [String] { return kind == "baseball" ? BASEBALL : TENNIS }
    override func OnPaint(_ e: PaintEventArgs) {
        let g = e.Graphics
        g.Clear(KEY)
        let art = BallForm.Art(kind)
        for r in 0..<8 {
            let row = Array(art[r])
            for i in 0..<8 {
                let c = row[i]
                if c == "." { continue }
                let b = c == "k" ? bk : (c == "T" ? bt : (c == "g" ? bg : (c == "R" ? brd : (c == "O" ? bo : (c == "o" ? bod : (c == "Y" ? byl : bw))))))
                g.FillRectangle(b, i * ps, r * ps, ps, ps)
            }
        }
    }
    override func OnMouseDown(_ e: MouseEventArgs) {
        super.OnMouseDown(e)
        if e.Button == MouseButtons.Left && Kicked != nil { Kicked!() }
    }
}

// 煙火（蓋住一整個螢幕、點得穿）
class FxForm: OverlayForm {
    let parts = List<Arr<Double>>() // x, y, vx, vy, 年齡, 壽命, 顏色, 種類(0 火箭 / 1 火花)
    let plan = List<Arr<Double>>()  // 時間, x, 目標 y, 顏色
    let k: Double
    let rnd = Random()
    let cols: [SolidBrush]
    var t = 0.0
    var Active = false

    init(_ k: Double) {
        self.k = k
        let rgb: [Int] = [0xFF5A5A, 0xFFD84A, 0x5AD1FF, 0xFF8FD8, 0x8CFF8C, 0xFFA64A]
        var cs: [SolidBrush] = []
        for i in 0..<rgb.count { cs.append(SolidBrush(Color.FromArgb((rgb[i] >> 16) & 255, (rgb[i] >> 8) & 255, rgb[i] & 255))) }
        cols = cs
        super.init(true)
    }

    func R(_ a: Double, _ b: Double) -> Double { return a + rnd.NextDouble() * (b - a) }

    // n 發；focusX ≥ 0 時集中在那附近（小煙火）
    func Start(_ area: Rectangle, _ n: Int, _ focusX: Int) {
        if !Active || Bounds != area { Bounds = area; parts.Clear(); plan.Clear(); t = 0 }
        Active = true
        var i = 0
        while i < n {
            let fx: Double = focusX >= 0 ? Math.Max(30.0, Math.Min(Double(area.Width - 30), Double(focusX - area.Left) + R(-160, 160) * k)) : R(0.12, 0.88) * Double(area.Width)
            let ty: Double = (focusX >= 0 ? R(0.35, 0.6) : R(0.12, 0.45)) * Double(area.Height)
            plan.Add(Arr<Double>([t + 0.32 * Double(i) + R(0, 0.2), fx, ty, Double(rnd.Next(cols.count))]))
            i += 1
        }
        if !Visible { Show() }
    }

    func Step(_ dt: Double) {
        if !Active { return }
        t += dt
        let h = Double(Height)
        var i = plan.Count - 1
        while i >= 0 {
            let q = plan[i]
            if t < q[0] { i -= 1; continue }
            parts.Add(Arr<Double>([q[1], h, 0, -(h - q[2]) / 0.45, 0, 0.45, q[3], 0]))
            plan.RemoveAt(i)
            i -= 1
        }
        i = parts.Count - 1
        while i >= 0 {
            let p = parts[i]
            p[4] += dt
            if p[7] == 0 {
                p[1] += p[3] * dt
                if p[4] >= p[5] {
                    let n = 40
                    for j in 0..<n {
                        let a = Math.PI * 2 * Double(j) / Double(n) + R(-0.1, 0.1), sp = R(170, 380) * k
                        let col: Double = rnd.NextDouble() < 0.7 ? p[6] : Double(rnd.Next(cols.count))
                        parts.Add(Arr<Double>([p[0], p[1], Math.Cos(a) * sp, Math.Sin(a) * sp, 0, R(0.7, 1.15), col, 1]))
                    }
                    parts.RemoveAt(i)
                }
            } else {
                p[3] += 260 * k * dt
                p[2] *= Math.Pow(0.35, dt); p[3] *= Math.Pow(0.6, dt)
                p[0] += p[2] * dt; p[1] += p[3] * dt
                if p[4] > p[5] { parts.RemoveAt(i) }
            }
            i -= 1
        }
        if plan.Count == 0 && parts.Count == 0 { Active = false; Hide(); return }
        Invalidate()
    }

    func Stop() { Active = false; plan.Clear(); parts.Clear(); Hide() }

    override func OnPaint(_ e: PaintEventArgs) {
        let g = e.Graphics
        g.Clear(KEY)
        for p in parts {
            let fading = p[7] == 1 && p[4] > p[5] * 0.7
            if fading && Math.Floor(p[4] * 24).truncatingRemainder(dividingBy: 2) == 0 { continue }
            let q = CInt(Math.Max(2.0, (p[7] == 0 || p[4] < p[5] * 0.45 ? 2.4 : 1.5) * k))
            let px = CInt(p[0]), py = CInt(p[1])
            let b = cols[CInt(p[6])]
            g.FillRectangle(b, px - q / 2, py - q / 2 - q, q, 3 * q)
            g.FillRectangle(b, px - q / 2 - q, py - q / 2, 3 * q, q)
        }
    }
}

// 大合照的閃光（點得穿、半透明白）
class FlashForm: OverlayForm {
    init() { super.init(true); BackColor = Color.White; TransparencyKey = Color.Empty; Opacity = 0 }
}

// 黏在視窗角落的小蜘蛛網
class CobwebForm: OverlayForm {
    let H: IntPtr
    let RightCorner: Bool
    let Born: Double
    let Side: Int
    let lw: Int

    init(_ h: IntPtr, _ right: Bool, _ side: Int, _ lw: Int, _ born: Double) {
        H = h; RightCorner = right; Side = side; self.lw = lw; Born = born
        super.init(true)
        Size = Size(side, side)
    }

    override func OnPaint(_ e: PaintEventArgs) {
        let g = e.Graphics
        g.Clear(KEY)
        let s = Side
        let ox: Double = RightCorner ? Double(s - 1) : 0, sx: Double = RightCorner ? -1 : 1
        let spokes = 5
        let rings: [Double] = [0.32, 0.58, 0.84]
        do {
            let p = Pen(Color.FromArgb(0x8E, 0x97, 0xB0), Double(lw))
            var pts = [[PointF]](repeating: [PointF](repeating: PointF(0, 0), count: rings.count), count: spokes)
            for i in 0..<spokes {
                let a = Math.PI / 2 * Double(i) / Double(spokes - 1)
                let dx = Math.Cos(a), dy = Math.Sin(a)
                let len = Double(s - lw - 1)
                g.DrawLine(p, ox, 0.0, ox + sx * dx * len, dy * len)
                for j in 0..<rings.count {
                    pts[i][j] = PointF(ox + sx * dx * len * rings[j], dy * len * rings[j])
                }
            }
            for j in 0..<rings.count {
                var i = 0
                while i + 1 < spokes {
                    let a = pts[i][j], b = pts[i + 1][j]
                    let mx: Double = (a.X + b.X) / 2 + (ox - (a.X + b.X) / 2) * 0.12
                    let my: Double = (a.Y + b.Y) / 2 * 0.88
                    let m = PointF(mx, my)
                    g.DrawLine(p, a, m)
                    g.DrawLine(p, m, b)
                    i += 1
                }
            }
        }
    }
}

// 公仔本體的視窗：畫面由 Pet 用 UpdateLayeredWindow 提供；滑鼠事件轉給 Pet
class PetForm: OverlayForm {
    let pet: Pet
    init(_ pet: Pet) { self.pet = pet; super.init(false, true) }
    override func OnPaint(_ e: PaintEventArgs) { }
    override func OnPaintBackground(_ e: PaintEventArgs) { }
    override func OnMouseDown(_ e: MouseEventArgs) { super.OnMouseDown(e); pet.MouseDown(e) }
    override func OnMouseUp(_ e: MouseEventArgs) {
        super.OnMouseUp(e)
        if e.Button == MouseButtons.Right {
            let c: Point = Cursor.Position
            let id: String = pet.P.Id ?? ""
            let at: String = "{X=" + String(c.X) + ",Y=" + String(c.Y) + "}"
            App.LogAlways("menu: right-up on pet " + id + " at " + at)
        }
        pet.MouseUp(e)
    }
}

