    // ---------------- 紅皮克敏：勇敢、有點衝，會冒小火花 ----------------
    static func PikRed() -> Pal {
        let p = PikBase("pkred", "紅皮克敏", 0xE8312F, 0xB4201F, 0xFF7A6A, 0x7A1414)
        p.Speed = 75; p.Move = "march"
        p.PikLines("小紅")
