        p.Say("tickle", "噗咿咿！癢！（電電）", "滋滋滋～嘻嘻", "再丟一次！"); p.Say("tickle_d", "噗咿…不鬧了…")
        p.Say("drag", "噗咿！要丟了嗎！要丟了嗎！"); p.Say("throw", "噗咿～～～飛高高！")
