    // ---------- 拉拉 × 小波：踢球、小波騎車去撿 ----------
    func SceneBallFetch(_ la: Pet, _ po: Pet) {
        Begin(la, po)
        let ball: [String] = la.P.Art["BALL"]
        // C# 的 tx／lying 是被 lambda 抓住的區域變數（共用）：用一個小盒子裝
        final class Box { var tx: Double = 0; var lying: Prop? = nil }
        let bx = Box()
        bx.tx = po.Cx
        At(0) { [self] in Face(la, po); la.ScenePose("idle", 30); po.ScenePose("idle", 30); la.Say("小波！我們來踢球！", 2) }
        At(2.0) { po.ScenePose("wave", 1.0); po.Say("好！Eh-oh!", 1.4) }
        At(3.4) { [self] in
            la.ScenePose("kick", 0.5); la.Say("踢～！", 1); la.LoseBall(true)
            let wa = WA(la.Cx, la.Foot - 4)
            let side: Double = po.Cx >= la.Cx ? 1 : -1
            bx.tx = World.Mid(po.Cx + side * 220 * k, Double(wa.Left + po.SW), Double(wa.Right - po.SW))
            bx.lying = Toss(ball, la.P, la.FootPoint(), PointF(bx.tx, la.Foot - 3.5 * Double(S)), 1.0, 130 * k, false, 30, nil)
        }
        At(3.9) { po.RaceTo(bx.tx); po.Say("我去撿！嘟嘟～", 1.6) }
        At(6.4) { [self] in RemoveProp(bx.lying); po.FaceTo(la); po.Say("找到了！", 1.4) }
        At(7.2) { [self] in Toss(ball, la.P, po.HandPoint(), la.HandPoint(), 0.9, 110 * k, false, 0) { la.LoseBall(false); la.ScenePose("twirl", 1.6); la.Say("再來一次！", 1.6); po.Say("再來一次！", 1.6) } }
        At(9.8) { po.WalkTo(la.Cx + (po.Cx < la.Cx ? -1 : 1) * Double(la.SW) * 1.0, 1.5) }
        At(12.0) { [self] in Face(la, po); la.ScenePose("hug", 2.4); po.ScenePose("hug", 2.4); la.Say("大抱抱！", 2.2); po.Say("大抱抱！", 2.2) }
        At(14.6) { }
    }

    // ---------- 大家：大抱抱 ----------
    func SceneBigHug() {
        let outs = OutPets()
        if outs.Count < 2 { AllOut(); Later(2.5) { [self] in SceneBigHug() }; return }
        let l: Pet = Lead()
        Begin(outs.ToArray())
        let lr = LineUp(ShowOrder(outs), l, 1.05)
        let all4 = outs.Count >= 4
        At(0) { l.Say(all4 ? "大家都到齊了！" : "大家過來～", 1.8) }
        At(4.8) {
            for p in outs { p.dir = p.Cx < (lr[0] + lr[1]) / 2 ? 1 : -1; p.ScenePose("hug", 3.4); p.Burst(5) }
            l.Say(all4 ? "四個一起，大～抱抱！" : "大抱抱！", 2.6)
        }
        At(8.6) { for p in outs { p.ScenePose("wave", 1.6) }; l.Say("Eh-oh! ♥", 1.6) }
        At(10.4) { }
    }

    static func SingLine(_ p: Pet) -> String {
        switch p.P.Id! {
        case "tinky": return "啦～啦～（丁丁跳舞）"
        case "dipsy": return "嘿～嘿～（打拍子）"
        case "laalaa": return "啦啦啦～♪"
        case "po": return "啦啦！再來一次！"
        default: break
        }
        return "♪～"
    }

    // ---------- 大家：拉拉起頭，一隻一隻加入唱歌跳舞 ----------
    func SceneSing() {
        let outs = OutPets()
        if outs.Count < 2 { AllOut(); Later(2.5) { [self] in SceneSing() }; return }
        let la = Get("laalaa")
        let starter: Pet = la != nil && la!.Out && outs.Contains(la!) ? la! : Lead()
        Begin(outs.ToArray())
        LineUp(ShowOrder(outs), Lead(), 1.8)
        At(0) { starter.Say("大家過來～我們來唱歌！", 2) }
        At(4.6) { for p in outs { p.FaceTo(starter); p.ScenePose("idle", 30) }; starter.ScenePose("sing", 30); starter.Say("啦啦啦～大家一起唱！♪", 2.4) }
        var d = 7.2
        for p in ShowOrder(outs) {
            if p === starter { continue }
            let pp = p
            At(d) { pp.ScenePose(pp.P.Id == "po" ? "spin" : "dance", 30); pp.Say(World.SingLine(pp), 2); pp.Mark(0) }
            d += 1.9
        }
        At(d + 0.4) { for p in outs { p.ScenePose(p.P.Id == "laalaa" ? "twirl" : "dance", 2.6); p.Mark(0); p.Mark(0) }; starter.Say("啦啦啦～大家一起～♪", 2.4) }
        At(d + 3.2) { for p in outs { p.ScenePose("wave", 1.6) }; starter.Say("再來一次！", 1.6) }
        At(d + 5.0) { }
    }

    // ---------- 大家：一、二、三，一起跌倒「哎喲！」 ----------
    func SceneFall() {
        let outs = OutPets()
        if outs.Count < 2 { AllOut(); Later(2.5) { [self] in SceneFall() }; return }
        let l: Pet = Lead()
        Begin(outs.ToArray())
        LineUp(ShowOrder(outs), l, 1.6)
        At(0) { l.Say("大家排好～", 1.6) }
        At(4.6) { for p in outs { p.ScenePose("idle", 30) }; l.Say("大家一起…一、二、三！", 2) }
        At(6.6) { for p in outs { p.ScenePose("hop", 0) } }
        At(7.3) { for p in outs { p.ScenePose("plop", 2.2); p.Mark(4) }; l.Say("哎喲！", 1.4) }
        At(9.5) { for p in outs { p.ScenePose("idle", 30) }; l.Say("嘻嘻嘻～大家都跌倒了", 1.8) }
        At(11.4) { l.Say("再來一次！", 1.6); for p in outs { p.ScenePose("hop", 0) } }
        At(12.8) { }
    }

    // ---------- 大家：吐司時間（吐司彈出來，屑屑掉滿地，吸吸來打掃）----------
    func SceneToast() {
        let outs = OutPets()
        if outs.Count < 2 { AllOut(); Later(2.5) { [self] in SceneToast() }; return }
        let l: Pet = Lead()
        Begin(outs.ToArray())
        let order = ShowOrder(outs)
        let lr = LineUp(order, l, 1.75)
        let cx = (lr[0] + lr[1]) / 2, foot = lr[2]
        At(0) { l.Say("吐司時間！🍞", 1.8) }
        At(4.2) { for p in outs { p.FaceTo(l); p.ScenePose("idle", 30) }; l.Say("吐司！吐司！吐司！", 2) }
        var d = 4.6
        for p in order {
            let pp = p
            At(d) { [self] in
                Toss(World.TOAST_ART, pp.P, PointF(cx, foot - 2 * Double(S)), pp.HandPoint(), 0.75, 170 * k, true, 0) { pp.HoldToast = true; pp.Say("吐司！", 0.65) }
            }
            d += 0.7
        }
        At(d + 0.8) { l.Say("好好吃～屑屑掉滿地了", 2) }
        At(d + 3.0) { order[order.Count - 1].Say("糟糕…要打掃了！", 1.8) }
        At(d + 3.6) { [self] in StartBot(cx, foot) }
        At(d + 4.6) { order[0].Say("吸吸來了！", 1.6); for p in outs { p.Mark(1) } }
        At(d + 6.8) { for p in outs { p.HoldToast = false; p.ClearCrumbs() }; l.Say("吸～吸～好乾淨！", 2) }
        At(d + 9.4) { for p in outs { p.ScenePose("wave", 1.6) }; l.Say("吸吸，謝謝你！Eh-oh!", 2) }
        At(d + 11.6) { }
    }

    // 吸吸：從比較近的螢幕邊滾進來，在大家腳邊來回吸，再滾出去
    func StartBot(_ cx: Double, _ foot: Double) {
        if Hidden { return }
        let wa = WA(cx, foot - 4)
        let ps = Math.Max(2, S * 3 / 4)
        let fromLeft = cx - Double(wa.Left) < Double(wa.Right) - cx
        let sx: Double = fromLeft ? Double(wa.Left - 8 * ps) : Double(wa.Right + 8 * ps)
        let ex: Double = fromLeft ? Double(wa.Right + 10 * ps) : Double(wa.Left - 10 * ps)
        let by: Double = foot - 4.5 * Double(ps) - Double(Math.Max(1, ps / 3))
        let owner = Pal.Get("tinky")!
        let b = NewProp(World.BOT_A, World.BOT_B, owner, ps, sx, by, false)
        let sweep = 90 * k, side: Double = fromLeft ? 1 : -1
        let t1 = Math.Min(3.0, Math.Abs(cx - sx) / (260 * k) + 0.6)
        b.Go(cx - side * sweep, by, t1, 0, nil)
         .Go(cx + side * sweep, by, 1.4, 0, nil)
         .Go(cx - side * sweep * 0.5, by, 1.0, 0, nil)
         .Go(cx + side * sweep * 0.3, by, 0.7, 0, nil)
         .Go(ex, by, Math.Min(3.0, Math.Abs(ex - cx) / (260 * k) + 0.6), 0, nil)
        b.Hold = 0
    }

    // ---------- 早上點名：丁丁！迪西！拉拉！小波！天線寶寶，Eh-oh! ----------
    func TubbyRollCall(_ ids: List<String>) {
        let order = List<Pet>()
        for id in Pal.LineupIds(lineup) { if ids.Contains(id) && Get(id) != nil { order.Add(Get(id)!) } }
        var d = 0.4
        for p in order {
            let pp = p
            Later(d) { [self] in if !pp.Out { BringOut(pp, false) } }
            Later(d + 0.7) { pp.Say(pp.P.Name + "！", 1.8) }
            d += 1.5
        }
        Later(d + 0.8) { [self] in
            for p in order { if p.Out && p.Grounded() { p.ScenePose("wave", 1.8); p.Say("Eh-oh!", 2) } }
            if order.Count > 0 { Lead().Say("天線寶寶，Eh-oh! ☀", 2.6) }
        }
    }

    // ---------- 天線寶寶說再見：一隻一隻揮手回櫃子；最後從櫃子裡再說一次再見 ----------
    func SceneByeBye(_ night: Bool) {
        let outs = ShowOrder(OutPets())
        if outs.Count == 0 { let l0: Pet = Lead(); l0.Say("天線寶寶說再見！再見～", 3); return }
        let lead: Pet = Lead()
        Begin(outs.ToArray())
        for p in outs { if p.Grounded() { p.ScenePose("idle", 60) } }
        var d = 0.2
        if night { for p in outs { let pp = p; At(d) { pp.Say(pp.L("nag"), 2.6) }; d += 2.8 } }
        At(d) { lead.Say("天線寶寶，說再見的時間到了～", 2.6) }
        d += 2.8
        for p in outs {
            let pp = p
            At(d) { pp.ScenePose("wave", 2.2); pp.Say(pp.P.Name + "說再見！👋", 2.2) }
            At(d + 1.7) { pp.InScene = false; if pp.Out { pp.StowToShelf(false) } }
            d += 2.6
        }
        let last = outs[outs.Count - 1]
        At(d + 0.4) { last.Say("天線寶寶說再見！再見～", 3) }
        At(d + 3.8) { [self] in let po: Pet = Get("po") ?? last; po.Say("……再見～（偷偷揮手）", 2.2) }
        At(d + 6.2) { }
    }
}

// ===== 95_standalone.swift =====
// 95_standalone.swift — 獨立版 Desk Pals.app（不用 VS Code）的開場：只有從 .app 包裡跑的時候才做事，
// VS Code 擴充套件編出來的那支（desk-pals.sh）、CI 的離屏測試（DESKPALS_OFFSCREEN=1）都不受影響。
//   ・已經開著：叫它出來打個招呼就結束（不會開兩個）
//   ・寫 ~/Library/Application Support/SpideyDesktop/standalone.json：VS Code 擴充套件看到就不再自己編一份、不建開機啟動，只負責連上
//   ・開機自動啟動：~/Library/LaunchAgents/local.spidey-pet.plist（跟擴充套件同一個 Label → 直接換成 .app 版，不會開兩次）
//     擴充套件那份還開著的話先請它收工，再換這個上來
//   ・還在「下載項目」／DMG 裡直接打開（App Translocation）：提醒先拖進「應用程式」，這次不設開機啟動
//   ・在 Finder／Launchpad 再點一次：叫公仔打招呼
// 由 99_main.swift 在 App.Main() 之前呼叫。
import AppKit
import Carbon

enum Standalone {
    static let Label = "local.spidey-pet"
    static var home: String { return NSHomeDirectory() + "/Library/Application Support/SpideyDesktop" }
    static var reopen: ReopenHandler? = nil

    static func Prepare() {
        let bundle = Bundle.main.bundlePath
        if !bundle.hasSuffix(".app") || App.Offscreen { return }
        let a = CommandLine.arguments   // （macOS 13 以後 Finder 不會再帶 -psn_ 參數）
        if a.count >= 2 && a[1].hasPrefix("--") { return }   // --preview 之類的開發用指令
        let sock = a.count >= 2 && !a[1].isEmpty ? a[1] : home + "/spidey.sock"
        let exe = Bundle.main.executablePath ?? (bundle + "/Contents/MacOS/DeskPals")
        let translocated = bundle.contains("/AppTranslocation/") || bundle.hasPrefix("/Volumes/")
        var tookOver = false
        if !translocated {
            WriteMarker(bundle, exe)
            CopyHooks()
            tookOver = EnsureLaunchAgent(exe)
        }
        if Send(sock, "act hi") {
            if !tookOver { exit(0) }
            // 擴充套件編的那份還開著：請它收工，換 .app 版上來
            _ = Send(sock, "quit")
            WaitUnlocked(sock + ".lock", 10)
        }
        if translocated { AskToMove() }
        reopen = ReopenHandler(sock)
        NotificationCenter.default.addObserver(forName: NSApplication.didFinishLaunchingNotification, object: nil, queue: .main) { _ in reopen?.Install() }
    }

    static func WriteMarker(_ bundle: String, _ exe: String) {
        let ver = (Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String) ?? "dev"
        let j: [String: String] = ["kind": "app", "app": bundle, "exe": exe, "version": ver]
        guard let data = try? JSONSerialization.data(withJSONObject: j, options: [.sortedKeys]) else { return }
        try? FileManager.default.createDirectory(atPath: home, withIntermediateDirectories: true)
        try? data.write(to: URL(fileURLWithPath: home + "/standalone.json"))
    }

    // Claude Code hooks 的設定指著 SpideyDesktop/claude-hook.js（Mac安裝說明這樣寫）：放一份過去
    static func CopyHooks() {
        for f in ["claude-hook.js", "ci-watch.js"] {
            guard let from = Bundle.main.path(forResource: (f as NSString).deletingPathExtension, ofType: "js"),
                  let a = FileManager.default.contents(atPath: from) else { continue }
            let to = home + "/" + f
            if FileManager.default.contents(atPath: to) != a { try? a.write(to: URL(fileURLWithPath: to)) }
        }
    }

    // 回傳 true＝原本是擴充套件的（desk-pals.sh），這次換成 .app 版
    @discardableResult
    static func EnsureLaunchAgent(_ exe: String) -> Bool {
        let dir = NSHomeDirectory() + "/Library/LaunchAgents"
        let plist = dir + "/" + Label + ".plist"
        let have = (try? String(contentsOfFile: plist, encoding: .utf8)) ?? ""
        if have.contains("<string>" + Esc(exe) + "</string>") { return false }   // 已經是我（使用者在系統設定關掉的話也還是這份，尊重他）
        let bid = Bundle.main.bundleIdentifier ?? ""
        let want = """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0"><dict>
          <key>Label</key><string>\(Label)</string>
          <key>ProgramArguments</key><array><string>\(Esc(exe))</string></array>
          <key>RunAtLoad</key><true/>
          <key>LimitLoadToSessionType</key><string>Aqua</string>
          <key>AssociatedBundleIdentifiers</key><string>\(Esc(bid))</string>
        </dict></plist>

        """
        try? FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)
        try? want.write(toFile: plist, atomically: true, encoding: .utf8)
        return have.contains("desk-pals.sh")
    }

    static func Esc(_ s: String) -> String {
        return s.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;").replacingOccurrences(of: ">", with: "&gt;")
    }

    static func AskToMove() {
        let app = NSApplication.shared
        app.setActivationPolicy(.accessory)
        app.activate(ignoringOtherApps: true)
        let al = NSAlert()
        al.messageText = "先把「Desk Pals」拖進「應用程式」資料夾"
        al.informativeText = "現在是直接從下載的地方（或磁碟映像檔）打開的：這次也能玩，但開機不會自動出現。\n\n把它拖進「應用程式」資料夾，再從那裡打開一次就好了。"
        al.addButton(withTitle: "好")
        al.runModal()
    }

    // 送一行給開著的公仔櫃（unix socket）；沒開回 false
    static func Send(_ path: String, _ line: String) -> Bool {
        let fd = socket(AF_UNIX, SOCK_STREAM, 0)
        if fd < 0 { return false }
        defer { close(fd) }
        var addr = sockaddr_un()
        addr.sun_family = sa_family_t(AF_UNIX)
        let bytes = Array(path.utf8)
        if bytes.count >= MemoryLayout.size(ofValue: addr.sun_path) { return false }
        withUnsafeMutableBytes(of: &addr.sun_path) { raw in
            for (i, b) in bytes.enumerated() { raw[i] = b }
            raw[bytes.count] = 0
        }
        addr.sun_len = UInt8(MemoryLayout<sockaddr_un>.size)
        let rc = withUnsafePointer(to: &addr) { p -> Int32 in
            p.withMemoryRebound(to: sockaddr.self, capacity: 1) { Darwin.connect(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size)) }
        }
        if rc != 0 { return false }
        let d = Array((line + "\n").utf8)
        _ = d.withUnsafeBufferPointer { write(fd, $0.baseAddress, $0.count) }
        usleep(150_000)
        return true
    }

    // 等舊的那個放掉單一執行個體的鎖（App.Run 用 sock.lock 的 flock）
    static func WaitUnlocked(_ lockPath: String, _ secs: Double) {
        let end = Date().addingTimeInterval(secs)
        while Date() < end {
            let fd = open(lockPath, O_RDWR)
            if fd < 0 { return }
            let free = flock(fd, LOCK_EX | LOCK_NB) == 0
            if free { flock(fd, LOCK_UN) }
            close(fd)
            if free { return }
            usleep(200_000)
        }
    }
}

// 在 Finder／Launchpad／Spotlight 再打開一次（App 已經開著）：系統送 reopen 事件 → 叫公仔打招呼
final class ReopenHandler: NSObject {
    let sock: String
    init(_ sock: String) { self.sock = sock }
    func Install() {
        NSAppleEventManager.shared().setEventHandler(self, andSelector: #selector(onReopen(_:withReply:)),
                                                     forEventClass: AEEventClass(kCoreEventClass), andEventID: AEEventID(kAEReopenApplication))
    }
    @objc func onReopen(_ e: NSAppleEventDescriptor, withReply r: NSAppleEventDescriptor) {
        let s = sock
        DispatchQueue.global().async { _ = Standalone.Send(s, "act hi") }
    }
}

// ===== 99_main.swift =====
// 程式進入點（App.Main 在 10_platform.swift）
Standalone.Prepare()   // 獨立版 Desk Pals.app 才有作用（95_standalone.swift）
App.Main()

